import { defaultProjects, defaultSettings } from '../types';
// JSON is the wire/storage format. Dates are converted only at the UI boundary.
export interface RecordData {
    id: string;
    [key: string]: any;
}
export type Entity = 'projects' | 'timeEntries' | 'settings' | 'overtimeAdjustments' | 'projectHoursAdjustments';
export const entities: Entity[] = ['projects', 'timeEntries', 'settings', 'overtimeAdjustments', 'projectHoursAdjustments'];
export interface VersionedRecord {
    version: number;
    data: RecordData;
    deleted?: boolean;
    deletedBy?: string;
    previousData?: RecordData;
    changedBy?: string;
    correctionVersion?: number;
    startedFrom?: number;
}
export interface TrackerState {
    version: number;
    activeSessionId: string | null;
    pausedProjectId: string | null;
}
export interface Conflict {
    id: string;
    version: number;
    command: Command;
    currentProjectId: string | null;
    currentStart: string | null;
    resolved: boolean;
}
export interface Snapshot {
    schemaVersion: 3;
    revision: number;
    state: TrackerState;
    records: Record<Entity, Record<string, VersionedRecord>>;
    conflicts: Record<string, Conflict>;
}
export interface Mutation {
    entity: Entity;
    id: string;
    expectedVersion: number;
    data: RecordData | null;
}
export interface Command {
    operationId: string;
    deviceId: string;
    intendedAt: string;
    issuedAt: string;
    expectedStateVersion: number;
    type: 'start' | 'stop' | 'switch' | 'break' | 'resume' | 'edit' | 'resolve';
    sessionId?: string | null;
    projectId?: string;
    expectedCorrectionVersion?: number;
    mutations?: Mutation[];
    pausedProjectId?: string | null;
    conflictId?: string;
    expectedConflictVersion?: number;
    resolution?: 'keep' | 'switch';
}
export interface Outcome {
    status: 'applied' | 'duplicate' | 'conflict' | 'rejected';
    revision: number;
    message?: string;
    sessionId?: string;
    conflictId?: string;
}
export interface Receipt {
    command: Command;
    outcome: Outcome;
}
export function emptySnapshot(): Snapshot {
    return { schemaVersion: 3, revision: 0, state: { version: 0, activeSessionId: null, pausedProjectId: null },
        records: { projects: Object.fromEntries(defaultProjects.map(p => [p.id, { version: 1, data: cleanRecord({ ...p, createdAt: p.createdAt.toISOString() }) }])), timeEntries: {}, settings: { settings: { version: 1, data: { id: 'settings', ...defaultSettings } } }, overtimeAdjustments: {}, projectHoursAdjustments: {} }, conflicts: {} };
}
export function cleanRecord(data: RecordData): RecordData {
    const result = JSON.parse(JSON.stringify(data));
    for (const k of ['userId', 'user_id', '_rev', '_meta', '_attachments', '_deleted', '_modified', 'isActive', 'totalTime', 'currentSessionStart', 'updatedAt', 'version'])
        delete result[k];
    for (const key of Object.keys(result))
        if (result[key] === null)
            delete result[key];
    return result;
}
export function records(s: Snapshot, entity: Entity): RecordData[] { return Object.values(s.records[entity]).filter(r => !r.deleted).map(r => r.data); }
export function safeId(id: unknown): id is string { return typeof id === 'string' && id.length > 0 && id.length <= 150 && !(id in Object.prototype); }
export function activeEntry(s: Snapshot): VersionedRecord | undefined { return s.state.activeSessionId && Object.prototype.hasOwnProperty.call(s.records.timeEntries, s.state.activeSessionId) ? s.records.timeEntries[s.state.activeSessionId] : undefined; }
export function canonical(value: unknown): string {
    if (Array.isArray(value))
        return '[' + value.map(canonical).join(',') + ']';
    if (value && typeof value === 'object')
        return '{' + Object.entries(value).filter(([, v]) => v !== undefined).sort(([a], [b]) => a.localeCompare(b)).map(([k, v]) => JSON.stringify(k) + ':' + canonical(v)).join(',') + '}';
    return JSON.stringify(value);
}
export function validateSnapshot(s: Snapshot): void {
    if (s.schemaVersion !== 3 || !Number.isSafeInteger(s.revision) || s.revision < 0)
        throw new Error('Unsupported snapshot');
    const open = records(s, 'timeEntries').filter(e => !e.endTime);
    if (open.length > 1 || (open[0]?.id ?? null) !== s.state.activeSessionId)
        throw new Error('Active sessions require migration review');
    if (s.state.pausedProjectId && (!s.records.projects[s.state.pausedProjectId] || s.records.projects[s.state.pausedProjectId].deleted))
        throw new Error('Paused project is missing');
    for (const entity of entities)
        for (const [id, r] of Object.entries(s.records[entity])) {
            if (id !== r.data.id || !safeId(id) || id === 'prototype' || !Number.isSafeInteger(r.version) || r.version < 1)
                throw new Error('Invalid record');
            if (r.deleted)
                continue;
            const d = r.data;
            if (entity === 'projects') {
                if (typeof d.name !== 'string' || !d.name || !['none', 'hours', 'percentage'].includes(d.targetType))
                    throw new Error('Invalid project');
                if (d.parentId) {
                    const parent = s.records.projects[d.parentId];
                    if (d.parentId === id || ['work', 'break'].includes(d.parentId) || !parent || parent.deleted || parent.data.parentId)
                        throw new Error('Invalid project hierarchy');
                }
            }
            if (entity === 'timeEntries' || entity === 'projectHoursAdjustments') {
                if (!s.records.projects[d.projectId] || s.records.projects[d.projectId].deleted)
                    throw new Error('Entry project is missing');
            }
            if (entity === 'timeEntries') {
                if (!Number.isFinite(Date.parse(d.startTime)))
                    throw new Error('Invalid start time');
                if (d.endTime && (!Number.isFinite(Date.parse(d.endTime)) || Date.parse(d.endTime) <= Date.parse(d.startTime)))
                    throw new Error('End must be after start');
                if (d.duration !== (d.endTime ? Date.parse(d.endTime) - Date.parse(d.startTime) : 0))
                    throw new Error('Invalid duration');
            }
            if (entity === 'settings' && (!Number.isFinite(d.dailyTargetHours) || d.dailyTargetHours < 0 || !Array.isArray(d.workdays) || d.workdays.some((v: number) => !Number.isInteger(v) || v < 0 || v > 6) || !Array.isArray(d.vacationDays)))
                throw new Error('Invalid settings');
            if ((entity === 'overtimeAdjustments' || entity === 'projectHoursAdjustments') && !Number.isFinite(d.hours))
                throw new Error('Invalid adjustment');
        }
    if (['work', 'break'].some(id => !s.records.projects[id] || s.records.projects[id].deleted) || !s.records.settings.settings || s.records.settings.settings.deleted)
        throw new Error('Built-in records are required');
}
/** Pure deterministic command resolver. No persistence or clocks hidden inside it. */
export function applyCommand(before: Snapshot, command: Command, now: number): {
    snapshot: Snapshot;
    outcome: Outcome;
} {
    const s: Snapshot = structuredClone(before);
    const c = structuredClone(command);
    const outcome = (status: Outcome['status'], message?: string): {
        snapshot: Snapshot;
        outcome: Outcome;
    } => ({ snapshot: status === 'rejected' ? before : s, outcome: { status, revision: status === 'rejected' ? before.revision : s.revision, ...(message ? { message } : {}) } });
    const conflict = (message: string) => {
        // Discard every tentative mutation before recording a conflict.
        Object.assign(s, structuredClone(before));
        const active = activeEntry(s)?.data;
        s.conflicts[c.operationId] = { id: c.operationId, version: 1, command: c, currentProjectId: active?.projectId ?? null, currentStart: active?.startTime ?? null, resolved: false };
        s.revision++;
        return { snapshot: s, outcome: { status: 'conflict' as const, revision: s.revision, message, conflictId: c.operationId } };
    };
    try {
        const at = Date.parse(c.intendedAt);
        if (!safeId(c.operationId) || !safeId(c.deviceId) || !Number.isSafeInteger(c.expectedStateVersion) || c.expectedStateVersion < 0 || !Number.isFinite(at) || !Number.isFinite(Date.parse(c.issuedAt)) || Date.parse(c.issuedAt) > now + 120000 || at > now + 120000 || at < Date.UTC(2000, 0, 1))
            return outcome('rejected', 'Check device clock and requested time');
        if (!['start', 'stop', 'switch', 'break', 'resume', 'edit', 'resolve'].includes(c.type))
            return outcome('rejected', 'Unsupported command');
        const active = activeEntry(s);
        let target = c.projectId;
        let tracking = c.type !== 'edit';
        if (c.type === 'resolve') {
            const f = c.conflictId && safeId(c.conflictId) ? s.conflicts[c.conflictId] : undefined;
            if (!f || f.resolved || f.version !== c.expectedConflictVersion || s.state.version !== c.expectedStateVersion)
                return outcome('rejected', 'Resolution changed; refresh and review');
            if (c.resolution !== 'keep' && c.resolution !== 'switch')
                return outcome('rejected', 'Choose a resolution');
            if (c.resolution === 'switch' && !['start', 'switch', 'break', 'resume'].includes(f.command.type))
                return outcome('rejected', 'Reload the record and explicitly reapply your edit');
            f.resolved = true;
            f.version++;
            if (c.resolution === 'keep')
                tracking = false;
            else
                target = f.command.projectId;
        }
        else if (c.type !== 'stop' && c.type !== 'edit' && s.state.version !== c.expectedStateVersion) {
            if (c.type === 'start' && active && active.data.projectId === target && active.startedFrom === c.expectedStateVersion && !c.sessionId)
                return outcome('duplicate');
            return conflict('Tracking changed on another device. Review the competing request.');
        }
        if (c.type === 'edit') {
            if (c.conflictId) {
                const f = safeId(c.conflictId) ? s.conflicts[c.conflictId] : undefined;
                if (!f || f.resolved || f.version !== c.expectedConflictVersion)
                    return outcome('rejected', 'Resolution changed; refresh and review');
                f.resolved = true;
                f.version++;
            }
            if (!c.mutations?.length && c.pausedProjectId === undefined)
                return outcome('duplicate');
            c.mutations ??= [];
            if (new Set(c.mutations.map(m => m.entity + ':' + m.id)).size !== c.mutations.length)
                return outcome('rejected', 'A record may appear only once per command');
            // State check prevents an edit/import from altering a newly started session.
            if (c.expectedStateVersion !== s.state.version)
                return conflict('Tracking changed; reload before reapplying this edit');
            for (const m of c.mutations) {
                if (!entities.includes(m.entity) || !safeId(m.id) || m.id === 'prototype' || !Number.isSafeInteger(m.expectedVersion) || m.expectedVersion < 0)
                    return outcome('rejected', 'Invalid mutation');
                if ((s.records[m.entity][m.id]?.version ?? 0) !== m.expectedVersion)
                    return conflict('Record changed; your draft has been preserved');
            }
            for (const m of c.mutations) {
                const old = s.records[m.entity][m.id];
                const data = m.data ? cleanRecord(m.data) : old?.data;
                if (!data)
                    return outcome('rejected', 'Record is missing');
                if (m.entity === 'timeEntries' && m.data)
                    data.duration = data.endTime ? Date.parse(data.endTime) - Date.parse(data.startTime) : 0;
                s.records[m.entity][m.id] = { version: (old?.version ?? 0) + 1, data, ...(m.data ? {} : { deleted: true, deletedBy: c.operationId }), previousData: old?.data, changedBy: c.operationId, ...(m.entity === 'timeEntries' ? { correctionVersion: (old?.correctionVersion ?? 0) + 1 } : {}) };
            }
            if (c.pausedProjectId !== undefined && c.pausedProjectId !== s.state.pausedProjectId) {s.state.pausedProjectId=c.pausedProjectId;s.state.version++;}
            // Imports may introduce exactly one open session. Deleting an active session clears it.
            const open = records(s, 'timeEntries').filter(e => !e.endTime);
            const nextActive = open[0]?.id ?? null;
            if (nextActive !== s.state.activeSessionId || c.mutations.some(m => m.entity === 'timeEntries' && m.id === s.state.activeSessionId)) {
                s.state.activeSessionId = nextActive;
                s.state.version++;
            }
            if (s.state.pausedProjectId && s.records.projects[s.state.pausedProjectId]?.deleted) {
                s.state.pausedProjectId = null;
                s.state.version++;
            }
        }
        else if (c.type === 'stop') {
            const entry = s.records.timeEntries[c.sessionId ?? ''];
            if (!entry || entry.deleted)
                return conflict('The referenced session no longer exists');
            if ((entry.correctionVersion ?? 0) !== (c.expectedCorrectionVersion ?? 0))
                return conflict('History was corrected; reload before changing this session');
            if (at <= Date.parse(entry.data.startTime))
                return outcome('rejected', 'End must be after start');
            if (entry.data.endTime && at >= Date.parse(entry.data.endTime))
                return outcome('duplicate');
            entry.data.endTime = c.intendedAt;
            entry.data.duration = at - Date.parse(entry.data.startTime);
            entry.version++;
            if (s.state.activeSessionId === c.sessionId) {
                s.state.activeSessionId = null;
                s.state.pausedProjectId = null;
                s.state.version++;
            }
        }
        else if (tracking) {
            if (c.type === 'start' && (active || c.sessionId))
                return conflict('Start requires the original idle state');
            if (c.type !== 'start' && c.type !== 'resolve' && c.sessionId !== s.state.activeSessionId)
                return conflict('The active session changed');
            if (c.type === 'break')
                target = 'break';
            if (c.type === 'resume')
                target = s.state.pausedProjectId ?? undefined;
            if (target && (!safeId(target) || !s.records.projects[target] || s.records.projects[target].deleted))
                return outcome('rejected', 'Project does not exist');
            if (!target && c.type !== 'resume')
                return outcome('rejected', 'Choose a project');
            if (active) {
                if (at <= Date.parse(active.data.startTime))
                    return outcome('rejected', 'Switch must be after the session start');
                active.data.endTime = c.intendedAt;
                active.data.duration = at - Date.parse(active.data.startTime);
                active.version++;
            }
            s.state.pausedProjectId = c.type === 'break' ? active?.data.projectId ?? null : null;
            s.state.activeSessionId = target ? `session_${c.operationId}` : null;
            if (target)
                s.records.timeEntries[s.state.activeSessionId!] = { version: 1, correctionVersion: 0, startedFrom: c.expectedStateVersion, data: { id: s.state.activeSessionId!, projectId: target, startTime: c.intendedAt, duration: 0 } };
            s.state.version++;
        }
        if (c.type !== 'edit' && c.mutations?.length) {
            for (const m of c.mutations) {
                if (m.entity !== 'timeEntries' || m.id === c.sessionId || !m.expectedVersion && !m.data)
                    return outcome('rejected', 'Invalid overlap mutation');
                if ((before.records.timeEntries[m.id]?.version ?? 0) !== m.expectedVersion)
                    return conflict('Overlapping history changed; review before reapplying');
            }
            for (const m of c.mutations) {
                const old = s.records.timeEntries[m.id];
                const data = m.data ? cleanRecord(m.data) : old?.data;
                if (!data)
                    return outcome('rejected', 'Overlapping entry is missing');
                if (m.data)
                    data.duration = data.endTime ? Date.parse(data.endTime) - Date.parse(data.startTime) : 0;
                s.records.timeEntries[m.id] = { version: (old?.version ?? 0) + 1, data, correctionVersion: (old?.correctionVersion ?? 0) + 1, ...(m.data ? {} : { deleted: true }) };
            }
        }
        validateSnapshot(s);
        s.revision++;
        return outcome('applied');
    }
    catch (e) {
        return outcome('rejected', e instanceof Error ? e.message : 'Invalid command');
    }
}
