import { addRxPlugin, createRxDatabase, RxCollection, RxDatabase } from 'rxdb';
import { getRxStorageDexie } from 'rxdb/plugins/storage-dexie';
import { RxDBDevModePlugin } from 'rxdb/plugins/dev-mode';
import { RxDBLeaderElectionPlugin } from 'rxdb/plugins/leader-election';
import { wrappedValidateAjvStorage } from 'rxdb/plugins/validate-ajv';
addRxPlugin(RxDBLeaderElectionPlugin);
if (import.meta.env.DEV)
    addRxPlugin(RxDBDevModePlugin);
export interface Stored {
    id: string;
    scope: string;
    kind: string;
    value: string;
}
export type TrackerDatabase = RxDatabase<{
    documents: RxCollection<Stored>;
}>;
let database: Promise<TrackerDatabase> | undefined;
export function getTrackerDatabase() {
    return database ??= createTrackerDatabase('timetracker_commands_v3');
}
export function createTrackerDatabase(name: string, ignoreDuplicate = false) {
    return createRxDatabase<{
        documents: RxCollection<Stored>;
    }>({ name, ignoreDuplicate, storage: wrappedValidateAjvStorage({ storage: getRxStorageDexie() }), multiInstance: true }).then(async (db) => {
        await db.addCollections({ documents: { schema: { version: 0, primaryKey: 'id', type: 'object', properties: { id: { type: 'string', maxLength: 300 }, scope: { type: 'string', maxLength: 150 }, kind: { type: 'string', maxLength: 30 }, value: { type: 'string' } }, required: ['id', 'scope', 'kind', 'value'] } } });
        return db;
    });
}
export async function read<T>(db: TrackerDatabase, id: string): Promise<T | undefined> { const doc = await db.documents.findOne(id).exec(); return doc ? JSON.parse(doc.value) : undefined; }
export async function write(db: TrackerDatabase, id: string, scope: string, kind: string, value: unknown) { await db.documents.incrementalUpsert({ id, scope, kind, value: JSON.stringify(value) }); }
export async function scopeKey(endpoint: string, account: string) {
    const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(new URL(endpoint).origin + '/' + account));
    return 'cloud_' + Array.from(new Uint8Array(digest), b => b.toString(16).padStart(2, '0')).join('');
}
