export type TargetType = 'none' | 'hours' | 'percentage';

export interface Project {
  version?: number;
  id: string;
  name: string;
  icon: string;
  color: string;
  targetType: TargetType;
  targetValue?: number; // Hours per month or percentage (0-100)
  initialHours?: number; // Starting hours for projects added mid-month
  budgetHours?: number; // Total hour budget for the project
  budgetDeadline?: string; // Budget deadline (YYYY-MM-DD)
  parentId?: string; // Parent project ID for sub-project hierarchy (max 1 level)
  isActive: boolean;
  totalTime: number;
  createdAt: Date;
}

export interface TimeEntry {
  version?: number;
  id: string;
  projectId: string;
  startTime: Date;
  endTime?: Date;
  duration: number;
  description?: string;
}

export interface Settings {
  version?: number;
  dailyTargetHours: number;
  workdays: number[];
  vacationDays: string[]; // Array of YYYY-MM-DD date strings
  trackingStartDate: string; // YYYY-MM-DD
  initialOvertimeHours?: number; // Carry-over overtime/undertime from before tracking
  paidOvertimePerMonth?: number; // Monthly overtime hours paid/compensated with salary
  paidOvertimeOverrides?: Record<string, number>; // Month-specific overrides (YYYY-MM -> hours)
  lastUpdatedAt?: string; // ISO timestamp for conflict resolution
}

export interface AppState {
  projects: Project[];
  timeEntries: TimeEntry[];
  activeProjectId: string | null;
  pausedProjectId: string | null; // Project that was paused when break started
  settings: Settings;
  currentSessionStart: Date | null;
}

