    private async updatePending() { const pending = await this.pending(); this.status({ pending: pending.length, confirmationPending: pending.length > 0 && (this.status$.value.confirmationPending || pending.some(p => Date.now() - Date.parse(p.command.issuedAt) >= 10000)), needsConfirmation: pending.filter(p => ['start', 'switch', 'break', 'resume'].includes(p.command.type) && !this.inFlight.has(p.command.operationId)).map(p => p.command) }); }
