import { TimeEntry, Project, Settings } from '../types';

// Date-only helpers to avoid timezone issues across locales/continents
export const dateToYMD = (date: Date): string => {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
};

export const parseYMDToDateLocal = (ymd: string): Date => {
  const [y, m, d] = ymd.split('-').map(Number);
  return new Date(y, (m || 1) - 1, d || 1);
};

export const formatDuration = (milliseconds: number): string => {
  const sign = milliseconds < 0 ? '-' : '';
  const abs = Math.abs(milliseconds);
  const hours = Math.floor(abs / (1000 * 60 * 60));
  const minutes = Math.floor((abs % (1000 * 60 * 60)) / (1000 * 60));
  return `${sign}${hours}h ${minutes}m`;
};

export const formatTime = (date: Date): string => {
  return date.toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' });
};

export const formatDate = (date: Date): string => {
  return date.toLocaleDateString('de-DE');
};

export const getDurationInHours = (milliseconds: number): number => {
  return milliseconds / (1000 * 60 * 60);
};

export const getMillisecondsFromHours = (hours: number): number => {
  return hours * 60 * 60 * 1000;
};

export const calculateTotalTimeForProject = (projectId: string, entries: TimeEntry[]): number => {
  return entries
    .filter(entry => entry.projectId === projectId && entry.endTime)
    .reduce((total, entry) => total + entry.duration, 0);
};

export const calculateTotalTimeForPeriod = (entries: TimeEntry[], startDate: Date, endDate: Date): number => {
  return entries
    .filter(entry => {
      const entryDate = new Date(entry.startTime);
      return entryDate >= startDate && entryDate <= endDate && entry.endTime;
    })
    .reduce((total, entry) => total + entry.duration, 0);
};

export const calculateMonthlyProgress = (
  project: Project, 
  entries: TimeEntry[], 
  settings: Settings,
  totalMonthlyHours?: number // Total hours worked across all projects this month
): number => {
  const now = new Date();
  const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
  const endOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0);
  
  const monthlyTime = calculateTotalTimeForPeriod(
    entries.filter(e => e.projectId === project.id),
    startOfMonth,
    endOfMonth
  );
  const monthlyHours = getDurationInHours(monthlyTime);
  
  if (project.targetType === 'none' || !project.targetValue) {
    return 0; // No target set
  }
  
  if (project.targetType === 'hours') {
    // Hours-based target
    const adjustedTarget = adjustTargetForVacationDays(project.targetValue, now, settings);
    return (monthlyHours / adjustedTarget) * 100;
  }
  
  if (project.targetType === 'percentage') {
    // Percentage-based target
    if (!totalMonthlyHours || totalMonthlyHours === 0) return 0;
    
    const actualPercentage = (monthlyHours / totalMonthlyHours) * 100;
    return (actualPercentage / project.targetValue) * 100;
  }
  
  return 0;
};

// Backward compatibility function - deprecated, use calculateMonthlyProgress instead
export const calculateMonthlyProgressLegacy = (
  projectId: string, 
  entries: TimeEntry[], 
  targetHours: number | undefined, 
  settings: Settings
): number => {
  const now = new Date();
  const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
  const endOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0);
  
  const monthlyTime = calculateTotalTimeForPeriod(
    entries.filter(e => e.projectId === projectId),
    startOfMonth,
    endOfMonth
  );
  
  if (!targetHours) {
    // Use proportional share of monthly target
    const totalProjectTargets = getTotalProjectTargets(entries, startOfMonth, endOfMonth);
    if (totalProjectTargets === 0) return 0;
    
    const proportionalTarget = (getDurationInHours(monthlyTime) / totalProjectTargets) * calculateMonthlyTargetHours(now, settings);
    return proportionalTarget > 0 ? (getDurationInHours(monthlyTime) / proportionalTarget) * 100 : 0;
  }
  
  // Adjust target hours based on vacation days in the month
  const adjustedTarget = adjustTargetForVacationDays(targetHours, now, settings);
  return (getDurationInHours(monthlyTime) / adjustedTarget) * 100;
};

export const calculateMonthlyTargetHours = (date: Date, settings: Settings): number => {
  const year = date.getFullYear();
  const month = date.getMonth();
  
  const trackingStart = settings.trackingStartDate ? parseYMDToDateLocal(settings.trackingStartDate) : null;

  // If tracking starts after the given month, there are no working days.
  if (trackingStart && (trackingStart.getFullYear() > year || (trackingStart.getFullYear() === year && trackingStart.getMonth() > month))) {
    return 0;
  }

  return getWorkingDaysInMonth(date, settings.workdays, settings.vacationDays, settings.trackingStartDate) * settings.dailyTargetHours;
};

export const adjustTargetForVacationDays = (targetHours: number, date: Date, settings: Settings): number => {
  const totalWorkingDaysInMonth = getWorkingDaysInMonth(date, settings.workdays, [], settings.trackingStartDate);
  const actualWorkingDays = getWorkingDaysInMonth(date, settings.workdays, settings.vacationDays, settings.trackingStartDate);

  if (totalWorkingDaysInMonth === 0) return targetHours;
  
  // Proportionally reduce target based on vacation days
  return targetHours * (actualWorkingDays / totalWorkingDaysInMonth);
};

export const getWorkingDaysInMonth = (date: Date, workdays: number[], vacationDays: string[] = [], trackingStartDate?: string): number => {
  const year = date.getFullYear();
  const month = date.getMonth();
  const daysInMonth = new Date(year, month + 1, 0).getDate();

  const trackingStart = trackingStartDate ? parseYMDToDateLocal(trackingStartDate) : null;

  let startDay = 1;
  if (trackingStart && trackingStart.getFullYear() === year && trackingStart.getMonth() === month) {
    startDay = trackingStart.getDate();
  }

  // If tracking starts after the given month, there are no working days.
  if (trackingStart && (trackingStart.getFullYear() > year || (trackingStart.getFullYear() === year && trackingStart.getMonth() > month))) {
    return 0;
  }
  
  let workingDays = 0;
  for (let day = startDay; day <= daysInMonth; day++) {
    const currentDate = new Date(year, month, day);
    const dayOfWeek = currentDate.getDay();
    const dateString = dateToYMD(currentDate);
    
    if (workdays.includes(dayOfWeek) && !vacationDays.includes(dateString)) {
      workingDays++;
    }
  }
  
  return workingDays;
};

const getTotalProjectTargets = (entries: TimeEntry[], startDate: Date, endDate: Date): number => {
  const projectTimes = new Map<string, number>();
  
  entries
    .filter(entry => {
      const entryDate = new Date(entry.startTime);
      return entryDate >= startDate && entryDate <= endDate && entry.endTime && entry.projectId !== 'break';
    })
    .forEach(entry => {
      const current = projectTimes.get(entry.projectId) || 0;
      projectTimes.set(entry.projectId, current + getDurationInHours(entry.duration));
    });
  
  return Array.from(projectTimes.values()).reduce((sum, hours) => sum + hours, 0);
};

export interface PaidOvertimeResult {
  totalPaidHours: number;
  monthlyBreakdown: Record<string, number>; // YYYY-MM -> paid hours
}

export const getMonthsInRange = (startDate: Date, endDate: Date): string[] => {
  if (startDate > endDate) return [];
  const months: string[] = [];
  let curYear = startDate.getFullYear();
  let curMonth = startDate.getMonth();
  const endYear = endDate.getFullYear();
  const endMonth = endDate.getMonth();

  while (curYear < endYear || (curYear === endYear && curMonth <= endMonth)) {
    const monthStr = `${curYear}-${String(curMonth + 1).padStart(2, '0')}`;
    months.push(monthStr);
    curMonth++;
    if (curMonth > 11) {
      curMonth = 0;
      curYear++;
    }
  }
  return months;
};

export const calculateTotalPaidOvertime = (
  entries: TimeEntry[],
  settings: Settings,
  asOfDate?: Date,
  monthlyOffsets: Record<string, number> = {}
): PaidOvertimeResult => {
  const defaultPaid = settings.paidOvertimePerMonth ?? 0;
  const overrides = settings.paidOvertimeOverrides ?? {};

  const hasOverrides = Object.keys(overrides).length > 0;
  if (defaultPaid <= 0 && !hasOverrides) {
    return { totalPaidHours: 0, monthlyBreakdown: {} };
  }

  const trackingStart = parseYMDToDateLocal(settings.trackingStartDate);
  const end = asOfDate ?? new Date();

  if (trackingStart > end) {
    return { totalPaidHours: 0, monthlyBreakdown: {} };
  }

  const months = getMonthsInRange(trackingStart, end);
  let totalPaidHours = 0;
  const monthlyBreakdown: Record<string, number> = {};

  for (const monthStr of months) {
    const allowance = overrides[monthStr] !== undefined ? overrides[monthStr] : defaultPaid;
    if (allowance <= 0) {
      continue;
    }

    const [yStr, mStr] = monthStr.split('-');
    const year = parseInt(yStr, 10);
    const monthIndex = parseInt(mStr, 10) - 1;

    const firstOfMonth = new Date(year, monthIndex, 1, 0, 0, 0, 0);
    const lastOfMonth = new Date(year, monthIndex + 1, 0, 23, 59, 59, 999);

    const monthStartDate = trackingStart > firstOfMonth ? trackingStart : firstOfMonth;
    const monthEndDate = end < lastOfMonth ? end : lastOfMonth;

    const workDays = getWorkingDaysInRange(
      monthStartDate,
      monthEndDate,
      settings.workdays,
      settings.vacationDays,
      settings.trackingStartDate
    );
    const expectedHours = workDays * settings.dailyTargetHours;

    const monthEntries = entries.filter(e => {
      if (e.projectId === 'break' || !e.endTime) return false;
      const t = new Date(e.startTime);
      return t >= firstOfMonth && t <= monthEndDate;
    });
    const workedDuration = monthEntries.reduce((sum, e) => sum + e.duration, 0);
    const workedHours = getDurationInHours(workedDuration) + (monthlyOffsets[monthStr] ?? 0);

    const monthOvertime = workedHours - expectedHours;

    if (monthOvertime > 0) {
      const paid = Math.min(monthOvertime, allowance);
      monthlyBreakdown[monthStr] = paid;
      totalPaidHours += paid;
    }
  }

  return { totalPaidHours, monthlyBreakdown };
};

export const calculateRawOvertime = (entries: TimeEntry[], settings: Settings, adjustmentHours: number = 0, asOfDate?: Date): number => {
  const totalWorkedHours = getDurationInHours(
    entries
      .filter(entry => entry.projectId !== 'break' && entry.endTime)
      .reduce((total, entry) => total + entry.duration, 0)
  );

  const workDays = getWorkDaysCount(entries, settings, asOfDate);
  const expectedHours = workDays * settings.dailyTargetHours;

  return totalWorkedHours - expectedHours + (settings.initialOvertimeHours ?? 0) + adjustmentHours;
};

export const calculateOvertime = (
  entries: TimeEntry[],
  settings: Settings,
  adjustmentHours: number = 0,
  asOfDate?: Date,
  monthlyOffsets: Record<string, number> = {}
): number => {
  const rawOvertime = calculateRawOvertime(entries, settings, adjustmentHours, asOfDate);
  const { totalPaidHours } = calculateTotalPaidOvertime(entries, settings, asOfDate, monthlyOffsets);
  return rawOvertime - totalPaidHours;
};

export const getWorkDaysCount = (_entries: TimeEntry[], settings: Settings, asOfDate?: Date): number => {
  const trackingStart = parseYMDToDateLocal(settings.trackingStartDate);
  const endDate = asOfDate ?? new Date();
  return getWorkingDaysInRange(trackingStart, endDate, settings.workdays, settings.vacationDays, settings.trackingStartDate);
};

export const generateTimeEntryId = (): string => {
  return `entry_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
};

export const calculateDailyProgress = (date: Date, entries: TimeEntry[], settings: Settings): {
  totalHours: number;
  targetHours: number;
  progress: number;
  canLeaveWork: boolean;
} => {
  const startOfDay = new Date(date.getFullYear(), date.getMonth(), date.getDate(), 0, 0, 0);
  const endOfDay = new Date(date.getFullYear(), date.getMonth(), date.getDate(), 23, 59, 59);
  
  const dailyTime = calculateTotalTimeForPeriod(
    entries.filter(e => e.projectId !== 'break'),
    startOfDay,
    endOfDay
  );
  
  const totalHours = getDurationInHours(dailyTime);
  const targetHours = settings.dailyTargetHours;
  const progress = targetHours > 0 ? (totalHours / targetHours) * 100 : 0;
  const canLeaveWork = totalHours >= targetHours;
  
  return {
    totalHours,
    targetHours,
    progress,
    canLeaveWork
  };
};

export const generateProjectId = (): string => {
  return `project_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
};

export const getWeekBoundaries = (date: Date): { start: Date; end: Date } => {
  const day = date.getDay(); // 0=Sun, 1=Mon, ...
  const diffToMonday = day === 0 ? -6 : 1 - day;
  const monday = new Date(date.getFullYear(), date.getMonth(), date.getDate() + diffToMonday, 0, 0, 0, 0);
  const sunday = new Date(monday.getFullYear(), monday.getMonth(), monday.getDate() + 6, 23, 59, 59, 999);
  return { start: monday, end: sunday };
};

export const getWorkingDaysInRange = (
  startDate: Date,
  endDate: Date,
  workdays: number[],
  vacationDays: string[] = [],
  trackingStartDate?: string,
): number => {
  const trackingStart = trackingStartDate ? parseYMDToDateLocal(trackingStartDate) : null;

  // If tracking hasn't started yet relative to the whole range, return 0
  if (trackingStart && trackingStart > endDate) return 0;

  let workingDays = 0;
  const cursor = new Date(startDate.getFullYear(), startDate.getMonth(), startDate.getDate());
  const endDay = new Date(endDate.getFullYear(), endDate.getMonth(), endDate.getDate());

  while (cursor <= endDay) {
    // Skip days before tracking started
    if (!trackingStart || cursor >= trackingStart) {
      const dayOfWeek = cursor.getDay();
      const dateString = dateToYMD(cursor);
      if (workdays.includes(dayOfWeek) && !vacationDays.includes(dateString)) {
        workingDays++;
      }
    }
    cursor.setDate(cursor.getDate() + 1);
  }

  return workingDays;
};

export const calculateTargetHoursForRange = (
  startDate: Date,
  endDate: Date,
  settings: Settings,
): number => {
  return getWorkingDaysInRange(startDate, endDate, settings.workdays, settings.vacationDays, settings.trackingStartDate) * settings.dailyTargetHours;
};

export interface DistributedHoursInput {
  projectId: string;
  projectName: string;
  periodHours: number;
}

export interface DistributedHoursResult {
  projectId: string;
  projectName: string;
  actualHours: number;
  distributedHours: number;
  percentage: number;
}

export const calculateDistributedHours = (
  breakdown: DistributedHoursInput[],
  totalPeriodHours: number,
): DistributedHoursResult[] => {
  const workEntry = breakdown.find(p => p.projectId === 'work');
  const workHours = workEntry?.periodHours ?? 0;
  const denominator = totalPeriodHours - workHours;

  return breakdown
    .filter(p => p.projectId !== 'work' && p.projectId !== 'break')
    .map(p => {
      const distributedHours = denominator > 0 && totalPeriodHours > 0
        ? p.periodHours * totalPeriodHours / denominator
        : p.periodHours;
      return {
        projectId: p.projectId,
        projectName: p.projectName,
        actualHours: p.periodHours,
        distributedHours,
        percentage: totalPeriodHours > 0 ? (distributedHours / totalPeriodHours) * 100 : 0,
      };
    });
};