import { BehaviorSubject } from 'rxjs';
export const updateAvailable$ = new BehaviorSubject(false);
let registration: ServiceWorkerRegistration | undefined;
let reloadAfterUpdate = false;
// The worker caches the application shell only. Commands always use the repository
// and its receipt protocol; no worker or unload handler is a second writer.
if (import.meta.env.PROD && 'serviceWorker' in navigator) {
    navigator.serviceWorker.addEventListener('controllerchange', () => {
        if (reloadAfterUpdate)
            window.location.reload();
    });
    void navigator.serviceWorker.register(`${import.meta.env.BASE_URL}sw.js`).then(current => {
        registration = current;
        if (current.waiting)
            updateAvailable$.next(true);
        current.addEventListener('updatefound', () => {
            const worker = current.installing;
            worker?.addEventListener('statechange', () => {
                if (worker.state === 'installed' && navigator.serviceWorker.controller) {
                    updateAvailable$.next(true);
                }
            });
        });
    }).catch(() => { });
}
export async function updateApp(reload = true) {
    if (registration?.waiting) {
        reloadAfterUpdate = reload;
        registration.waiting.postMessage({ type: 'SKIP_WAITING' });
    }
}
