import { createRxDatabase, RxDatabase, RxCollection, addRxPlugin } from 'rxdb';
import { getRxStorageDexie } from 'rxdb/plugins/storage-dexie';
import { RxDBDevModePlugin } from 'rxdb/plugins/dev-mode';
import { RxDBQueryBuilderPlugin } from 'rxdb/plugins/query-builder';
import { RxDBMigrationSchemaPlugin } from 'rxdb/plugins/migration-schema';
import { wrappedValidateAjvStorage } from 'rxdb/plugins/validate-ajv';

// Add query-builder plugin (always needed)
addRxPlugin(RxDBQueryBuilderPlugin);
addRxPlugin(RxDBMigrationSchemaPlugin);
import {
  projectSchema,
  timeEntrySchema,
  settingsSchema,
  appStateSchema,
  overtimeAdjustmentSchema,
  projectHoursAdjustmentSchema,
  ProjectDocument,
  TimeEntryDocument,
  SettingsDocument,
  AppStateDocument,
  OvertimeAdjustmentDocument,
  ProjectHoursAdjustmentDocument,
} from './schemas';

// Add dev-mode plugin in development
if (import.meta.env.DEV) {
  addRxPlugin(RxDBDevModePlugin);
}

// Collection types
export type ProjectCollection = RxCollection<ProjectDocument>;
export type TimeEntryCollection = RxCollection<TimeEntryDocument>;
export type SettingsCollection = RxCollection<SettingsDocument>;
export type AppStateCollection = RxCollection<AppStateDocument>;
export type OvertimeAdjustmentCollection = RxCollection<OvertimeAdjustmentDocument>;
export type ProjectHoursAdjustmentCollection = RxCollection<ProjectHoursAdjustmentDocument>;

// Database type
export type TimeTrackerDatabase = RxDatabase<{
  projects: ProjectCollection;
  timeEntries: TimeEntryCollection;
  settings: SettingsCollection;
  appState: AppStateCollection;
  overtimeAdjustments: OvertimeAdjustmentCollection;
  projectHoursAdjustments: ProjectHoursAdjustmentCollection;
}>;

// Singleton database instance
let dbPromise: Promise<TimeTrackerDatabase> | null = null;

// Default data
const DEFAULT_PROJECTS: Omit<ProjectDocument, 'updatedAt'>[] = [
  {
    id: 'break',
    name: 'Break',
    icon: '☕',
    color: '#ff9800',
    targetType: 'none',
    isActive: false,
    totalTime: 0,
    createdAt: new Date().toISOString(),
  },
  {
    id: 'work',
    name: 'Work',
    icon: '💼',
    color: '#2196f3',
    targetType: 'none',
    isActive: false,
    totalTime: 0,
    createdAt: new Date().toISOString(),
  },
];

const DEFAULT_SETTINGS: Omit<SettingsDocument, 'updatedAt'> = {
  id: 'settings',
  dailyTargetHours: 8,
  workdays: [1, 2, 3, 4, 5],
  vacationDays: [],
  trackingStartDate: new Date().toISOString().split('T')[0],
  paidOvertimePerMonth: 0,
  paidOvertimeOverrides: {},
};

const DEFAULT_APP_STATE: AppStateDocument = {
  id: 'appState',
  themeMode: 'light',
};

// Migration from old localStorage
async function migrateFromLocalStorage(db: TimeTrackerDatabase): Promise<boolean> {
  const oldProjectsKey = 'timeTracker_projects';
  const oldData = localStorage.getItem(oldProjectsKey);

  if (!oldData || localStorage.getItem('timeTracker_legacyMigrationComplete') === 'true') {
    return false;
  }

  console.log('Migrating data from localStorage to RxDB...');

  try {
    // Load old data
    const oldProjects = JSON.parse(localStorage.getItem('timeTracker_projects') || '[]');
    const oldTimeEntries = JSON.parse(localStorage.getItem('timeTracker_timeEntries') || '[]');
    const oldSettings = JSON.parse(localStorage.getItem('timeTracker_settings') || '{}');
    const oldActiveProjectId = localStorage.getItem('timeTracker_activeProject');
    const oldPausedProjectId = localStorage.getItem('timeTracker_pausedProject');
    const oldCurrentSession = localStorage.getItem('timeTracker_currentSession');

    const now = new Date().toISOString();

    // Migrate projects
    if (oldProjects.length > 0) {
      const projectDocs = oldProjects.map((p: Record<string, unknown>) => ({
        id: p.id as string,
        name: p.name as string,
        icon: p.icon as string,
        color: p.color as string,
        targetType: (p.targetType as string) || 'none',
        targetValue: p.targetValue as number | undefined,
        initialHours: p.initialHours as number | undefined,
        isActive: Boolean(p.isActive),
        currentSessionStart: p.currentSessionStart as string | undefined,
        totalTime: (p.totalTime as number) || 0,
        createdAt: p.createdAt ? new Date(p.createdAt as string).toISOString() : now,
        updatedAt: now,
      }));
      const projectsResult = await db.projects.bulkUpsert(projectDocs);
      if (projectsResult.error.length) throw new Error('Legacy project migration failed; source is preserved');
      console.log(`Migrated ${projectDocs.length} projects`);
    }

    // Migrate time entries
    if (oldTimeEntries.length > 0) {
      const entryDocs = oldTimeEntries.map((e: Record<string, unknown>) => ({
        id: e.id as string,
        projectId: e.projectId as string,
        startTime: new Date(e.startTime as string).toISOString(),
        endTime: e.endTime ? new Date(e.endTime as string).toISOString() : undefined,
        duration: (e.duration as number) || 0,
        description: e.description as string | undefined,
        updatedAt: now,
      }));
      const entriesResult = await db.timeEntries.bulkUpsert(entryDocs);
      if (entriesResult.error.length) throw new Error('Legacy entry migration failed; source is preserved');
      console.log(`Migrated ${entryDocs.length} time entries`);
    }

    // Migrate settings
    if (Object.keys(oldSettings).length > 0) {
      await db.settings.upsert({
        id: 'settings',
        dailyTargetHours: oldSettings.dailyTargetHours || 8,
        workdays: oldSettings.workdays || [1, 2, 3, 4, 5],
        vacationDays: oldSettings.vacationDays || [],
        trackingStartDate: oldSettings.trackingStartDate || new Date().toISOString().split('T')[0],
        updatedAt: now,
      });
      console.log('Migrated settings');
    }

    // Migrate app state
    const themeMode = localStorage.getItem('timeTracker_themeMode');
    await db.appState.upsert({
      id: 'appState',
      activeProjectId: oldActiveProjectId || undefined,
      pausedProjectId: oldPausedProjectId || undefined,
      currentSessionStart: oldCurrentSession ? JSON.parse(oldCurrentSession) : undefined,
      themeMode: (themeMode === 'dark' ? 'dark' : 'light'),
    });

    // Preserve the source for review/recovery. Record completion separately.
    localStorage.setItem('timeTracker_legacyMigrationComplete', 'true');

    console.log('Migration from localStorage complete!');
    return true;
  } catch (error) {
    console.error('Migration failed:', error);
    throw error;
  }
}

// Initialize with defaults if empty
async function initializeDefaults(db: TimeTrackerDatabase): Promise<void> {
  const now = new Date().toISOString();

  // Check if projects exist
  const projectCount = await db.projects.count().exec();
  if (projectCount === 0) {
    console.log('Initializing default projects...');
    await db.projects.bulkInsert(
      DEFAULT_PROJECTS.map(p => ({ ...p, updatedAt: now }))
    );
  }

  // Check if settings exist
  const settings = await db.settings.findOne('settings').exec();
  if (!settings) {
    console.log('Initializing default settings...');
    await db.settings.insert({ ...DEFAULT_SETTINGS, updatedAt: now });
  }

  // Check if app state exists
  const appState = await db.appState.findOne('appState').exec();
  if (!appState) {
    console.log('Initializing default app state...');
    await db.appState.insert(DEFAULT_APP_STATE);
  }
}

// Create or get database
export async function getDatabase(): Promise<TimeTrackerDatabase> {
  if (dbPromise) {
    return dbPromise;
  }

  dbPromise = createDatabaseWithFallback();
  return dbPromise;
}

// Never erase a database when a schema cannot be opened. The recovery screen can
// export the original IndexedDB stores without needing the RxDB schema.
async function createDatabaseWithFallback(): Promise<TimeTrackerDatabase> {
  try { return await createDatabase(); }
  catch (error) { dbPromise = null; throw error; }
}

async function createDatabase(): Promise<TimeTrackerDatabase> {
  console.log('Creating RxDB database...');

  // Use Dexie storage (IndexedDB-based, free)
  const baseStorage = getRxStorageDexie();

  // Add validation in dev mode
  const storage = import.meta.env.DEV
    ? wrappedValidateAjvStorage({ storage: baseStorage })
    : baseStorage;

  const db = await createRxDatabase<TimeTrackerDatabase>({
    name: 'timetrackerdb',
    storage,
    multiInstance: true, // Allow multiple tabs
    eventReduce: true, // Optimize event handling
  });

  console.log('Adding collections...');

  await db.addCollections({
    projects: {
      schema: projectSchema,
      migrationStrategies: {
        // v0 -> v1: added optional parentId field
        1: (oldDoc: Record<string, unknown>) => oldDoc,
        // v1 -> v2: added optional budgetHours + budgetDeadline fields
        2: (oldDoc: Record<string, unknown>) => oldDoc,
        // v2 -> v3: added optional currentSessionStart field
        3: (oldDoc: Record<string, unknown>) => oldDoc,
        // v3 -> v4: added optional userId field; backfill with 'local' for existing local docs
        4: (oldDoc: Record<string, unknown>) => ({ ...oldDoc, userId: (oldDoc.userId as string | undefined) ?? 'local' }),
      },
    },
    timeEntries: {
      schema: timeEntrySchema,
      migrationStrategies: {
        // v0 -> v1: added optional userId field
        1: (oldDoc: Record<string, unknown>) => oldDoc,
      },
    },
    settings: {
      schema: settingsSchema,
      migrationStrategies: {
        // v0 -> v1: added optional initialOvertimeHours field
        1: (oldDoc: Record<string, unknown>) => oldDoc,
        // v1 -> v2: added optional idleThresholdHours field
        2: (oldDoc: Record<string, unknown>) => oldDoc,
        // v2 -> v3: removed idleThresholdHours field
        3: (oldDoc: Record<string, unknown>) => {
          const { idleThresholdHours: _removed, ...rest } = oldDoc;
          return rest;
        },
        // v3 -> v4: added optional userId field
        4: (oldDoc: Record<string, unknown>) => oldDoc,
        // v4 -> v5: added optional paidOvertimePerMonth and paidOvertimeOverrides fields
        5: (oldDoc: Record<string, unknown>) => ({
          ...oldDoc,
          paidOvertimePerMonth: (oldDoc.paidOvertimePerMonth as number | undefined) ?? 0,
          paidOvertimeOverrides: (oldDoc.paidOvertimeOverrides as Record<string, number> | undefined) ?? {},
        }),
      },
    },
    appState: {
      schema: appStateSchema,
      migrationStrategies: {
        // v0 -> v1: replace syncCode with supabaseUrl/supabaseAnonKey
        1: (oldDoc: Record<string, unknown>) => {
          const { syncCode: _removed, ...rest } = oldDoc;
          return rest;
        },
        // v1 -> v2: rename supabaseAnonKey to supabaseApiKey
        2: (oldDoc: Record<string, unknown>) => {
          const { supabaseAnonKey, ...rest } = oldDoc;
          return { ...rest, ...(supabaseAnonKey ? { supabaseApiKey: supabaseAnonKey } : {}) };
        },
        // v2 -> v3: added optional lastActivityAt field
        3: (oldDoc: Record<string, unknown>) => oldDoc,
        // v3 -> v4: removed lastActivityAt field
        4: (oldDoc: Record<string, unknown>) => {
          const { lastActivityAt: _removed, ...rest } = oldDoc;
          return rest;
        },
      },
    },
    overtimeAdjustments: {
      schema: overtimeAdjustmentSchema,
      migrationStrategies: {
        // v0 -> v1: added optional userId field
        1: (oldDoc: Record<string, unknown>) => oldDoc,
      },
    },
    projectHoursAdjustments: {
      schema: projectHoursAdjustmentSchema,
      migrationStrategies: {
        // v0 -> v1: added optional userId field
        1: (oldDoc: Record<string, unknown>) => oldDoc,
      },
    },
  });

  // Try to migrate from localStorage
  const migrated = await migrateFromLocalStorage(db);

  // Initialize defaults if needed
  if (!migrated) {
    await initializeDefaults(db);
  }

  console.log('RxDB database ready!');
  return db;
}
