import React, { useState, useEffect } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Button,
  Box,
  Typography,
  IconButton,
  FormControl,
  FormLabel,
  RadioGroup,
  FormControlLabel,
  Radio,
  Select,
  MenuItem,
  InputLabel
} from '@mui/material';
import { TargetType, Project } from '../types';
import { getDurationInHours } from '../utils/timeUtils';

interface EditProjectDialogProps {
  open: boolean;
  onClose: () => void;
  project: Project | null;
  onSave: (projectId: string, updates: {
    version?: number;
    name: string;
    icon: string;
    color: string;
    targetType: TargetType;
    targetValue?: number;
    initialHours?: number;
    budgetHours?: number;
    budgetDeadline?: string;
    parentId?: string;
  }) => void;
  onDelete?: (projectId: string, expectedVersion?: number) => void;
  availableParents?: Project[];
}

const COMMON_EMOJIS = ['💼', '📊', '🔬', '🎨', '📝', '📞', '🏠', '🚗', '🏋️', '📚', '🛒', '🍳', '⚽', '🎵', '💻', '🌟', '🔥', '💡', '🎯', '🏆', '📱', '⌚', '🎮', '📷', '✈️', '🍕', '☕', '🌍', '❤️', '🚀'];

export const EditProjectDialog: React.FC<EditProjectDialogProps> = ({ open, onClose, project, onSave, onDelete, availableParents = [] }) => {
  const [name, setName] = useState('');
  const [selectedIcon, setSelectedIcon] = useState('');
  const [customIcon, setCustomIcon] = useState('');
  const [selectedColor, setSelectedColor] = useState('');
  const [targetType, setTargetType] = useState<TargetType>('none');
  const [targetValue, setTargetValue] = useState<string>('');
  const [additionalHours, setAdditionalHours] = useState<string>('');
  const [budgetHours, setBudgetHours] = useState<string>('');
  const [budgetDeadline, setBudgetDeadline] = useState<string>('');
  const [parentId, setParentId] = useState<string>('');

  // Initialize form with project data when dialog opens
  useEffect(() => {
    if (open && project) {
      setName(project.name);
      setSelectedIcon(project.icon);
      setCustomIcon('');
      setSelectedColor(project.color);
      setTargetType(project.targetType);
      setTargetValue(project.targetValue ? project.targetValue.toString() : '');
      setAdditionalHours('');
      setBudgetHours(project.budgetHours ? project.budgetHours.toString() : '');
      setBudgetDeadline(project.budgetDeadline || '');
      setParentId(project.parentId || '');
    }
  }, [open, project]);

  const [submitting,setSubmitting] = React.useState(false);
  const handleSubmit = async () => {
    if(submitting)return;
    setSubmitting(true);
    try {
    if (name.trim() && project) {
      const finalIcon = customIcon.trim() || selectedIcon;
      await onSave(project.id, {
        version: project.version,
        name: name.trim(),
        icon: finalIcon,
        color: selectedColor,
        targetType,
        targetValue: targetType !== 'none' && targetValue ? parseFloat(targetValue) : undefined,
        initialHours: (project.initialHours || 0) + (additionalHours ? parseFloat(additionalHours) : 0),
        budgetHours: budgetHours ? parseFloat(budgetHours) : undefined,
        budgetDeadline: budgetDeadline || undefined,
        parentId: parentId || undefined,
      });
      handleClose();
    }
    } catch { /* Keep the draft; repository status displays the failure. */ } finally {setSubmitting(false);}
  };

  const handleClose = () => {
    setName('');
    setSelectedIcon('');
    setCustomIcon('');
    setSelectedColor('');
    setTargetType('none');
    setTargetValue('');
    setAdditionalHours('');
    setBudgetHours('');
    setBudgetDeadline('');
    setParentId('');
    onClose();
  };

  const handleDelete = async () => {
    if(submitting)return;
    setSubmitting(true);
    try {
    if (project && onDelete && window.confirm(`Are you sure you want to delete "${project.name}"? This action cannot be undone.`)) {
      await onDelete(project.id, project.version);
      handleClose();
    }
    } catch { /* Keep the draft; repository status displays the failure. */ } finally {setSubmitting(false);}
  };

  if (!project) return null;

  const currentTotalHours = getDurationInHours(project.totalTime);

  return (
    <Dialog open={open} onClose={handleClose} maxWidth="sm" fullWidth>
      <DialogTitle>Edit Project: {project.name}</DialogTitle>
      <DialogContent>
        <TextField
          autoFocus
          margin="dense"
          label="Project Name"
          fullWidth
          variant="outlined"
          value={name}
          onChange={(e) => setName(e.target.value)}
          sx={{ mb: 3 }}
        />

        {availableParents.length > 0 && project && project.id !== 'break' && project.id !== 'work' && (
          <FormControl fullWidth margin="dense" sx={{ mb: 2 }}>
            <InputLabel id="edit-parent-project-label">Parent Project (optional)</InputLabel>
            <Select
              labelId="edit-parent-project-label"
              value={parentId}
              label="Parent Project (optional)"
              onChange={(e) => setParentId(e.target.value)}
            >
              <MenuItem value="">
                <em>None (top-level project)</em>
              </MenuItem>
              {availableParents
                .filter((p) => p.id !== project.id) // Can't be own parent
                .map((p) => (
                  <MenuItem key={p.id} value={p.id}>
                    {p.icon} {p.name}
                  </MenuItem>
                ))}
            </Select>
          </FormControl>
        )}

        <Box sx={{ mb: 3 }}>
          <FormControl component="fieldset">
            <FormLabel component="legend">Monthly Target</FormLabel>
            <RadioGroup
              value={targetType}
              onChange={(e) => setTargetType(e.target.value as TargetType)}
              row
            >
              <FormControlLabel value="none" control={<Radio />} label="No Target" />
              <FormControlLabel value="hours" control={<Radio />} label="Hours" />
              <FormControlLabel value="percentage" control={<Radio />} label="Percentage" />
            </RadioGroup>
          </FormControl>
          
          {targetType !== 'none' && (
            <TextField
              margin="normal"
              label={targetType === 'hours' ? 'Target Hours per Month' : 'Target Percentage'}
              type="number"
              fullWidth
              variant="outlined"
              value={targetValue}
              onChange={(e) => setTargetValue(e.target.value)}
              inputProps={{ 
                min: 0, 
                max: targetType === 'percentage' ? 100 : undefined,
                step: targetType === 'percentage' ? 1 : 0.5 
              }}
              helperText={targetType === 'hours' ? 'Total hours to work on this project per month' : 'Percentage of total work time for this project (0-100%)'}
            />
          )}
        </Box>
        
        <Box sx={{ mb: 3, p: 2, backgroundColor: 'grey.50', borderRadius: 1 }}>
          <Typography variant="body2" color="text.secondary" gutterBottom>
            <strong>Current total hours:</strong> {currentTotalHours.toFixed(1)}h
          </Typography>
          <TextField
            margin="normal"
            label="Add Additional Hours (optional)"
            type="number"
            fullWidth
            variant="outlined"
            value={additionalHours}
            onChange={(e) => setAdditionalHours(e.target.value)}
            inputProps={{ min: 0, step: 0.5 }}
            helperText="Add hours to the total (e.g., if you worked offline or forgot to track)"
            sx={{ mt: 1 }}
          />
        </Box>

        <Box sx={{ mb: 3, p: 2, border: '1px solid', borderColor: 'divider', borderRadius: 1 }}>
          <Typography variant="subtitle2" gutterBottom>
            Hour Budget (optional)
          </Typography>
          <TextField
            margin="dense"
            label="Total Budget Hours"
            type="number"
            fullWidth
            variant="outlined"
            value={budgetHours}
            onChange={(e) => setBudgetHours(e.target.value)}
            inputProps={{ min: 0, step: 0.5 }}
            helperText="Total hours allocated for this project"
            sx={{ mb: 1 }}
          />
          <TextField
            margin="dense"
            label="Deadline"
            type="date"
            fullWidth
            variant="outlined"
            value={budgetDeadline}
            onChange={(e) => setBudgetDeadline(e.target.value)}
            slotProps={{ inputLabel: { shrink: true } }}
            helperText="Budget deadline date"
          />
        </Box>

        <Typography variant="h6" gutterBottom>
          Project Icon
        </Typography>
        
        <Box sx={{ display: 'flex', gap: 2, alignItems: 'center', mb: 2 }}>
          <Box sx={{ 
            width: 64, 
            height: 64, 
            display: 'flex', 
            alignItems: 'center', 
            justifyContent: 'center',
            border: '2px solid',
            borderColor: 'primary.main',
            borderRadius: 1,
            backgroundColor: selectedColor,
            color: 'white',
            fontSize: '2rem'
          }}>
            {customIcon || selectedIcon}
          </Box>
        </Box>

        <TextField
          label="Custom Emoji (or use suggestions below)"
          value={customIcon}
          onChange={(e) => {
            setCustomIcon(e.target.value);
            setSelectedIcon(''); // Clear selected when typing custom
          }}
          fullWidth
          margin="normal"
          helperText="Type any emoji or leave empty to keep current"
          sx={{ mb: 2 }}
        />

        <Typography variant="body2" gutterBottom>
          Quick suggestions:
        </Typography>
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mb: 3 }}>
          {COMMON_EMOJIS.slice(0, 15).map((emoji) => (
            <IconButton
              key={emoji}
              onClick={() => {
                setSelectedIcon(emoji);
                setCustomIcon('');
              }}
              sx={{ 
                width: 40, 
                height: 40,
                border: selectedIcon === emoji ? '2px solid' : '1px solid transparent',
                borderColor: selectedIcon === emoji ? 'primary.main' : 'transparent'
              }}
            >
              <Typography variant="body1">{emoji}</Typography>
            </IconButton>
          ))}
        </Box>

        <Typography variant="h6" gutterBottom>
          Project Color
        </Typography>
        <Box sx={{ display: 'flex', gap: 2, alignItems: 'center', mb: 2 }}>
          <input
            type="color"
            value={selectedColor}
            onChange={(e) => setSelectedColor(e.target.value)}
            style={{
              width: '60px',
              height: '40px',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer'
            }}
          />
          <Typography variant="body2" color="text.secondary">
            {selectedColor}
          </Typography>
        </Box>
      </DialogContent>
      <DialogActions>
        {onDelete && (
          <Button disabled={submitting}
            onClick={handleDelete} 
            color="error"
            sx={{ mr: 'auto' }}
          >
            Delete Project
          </Button>
        )}
        <Button onClick={handleClose}>Cancel</Button>
        <Button 
          onClick={handleSubmit} 
          variant="contained"
          disabled={submitting || (!name.trim())}
        >
          Save Changes
        </Button>
      </DialogActions>
    </Dialog>
  );
};