import { createContext, useContext, useEffect, useState, ReactNode, useRef } from 'react';
import { createClient, SupabaseClient, User } from '@supabase/supabase-js';
import { Alert, Button, Box, Typography } from '@mui/material';
import { getDatabase } from '../db';
import { TrackerRepository, LocalTrackerRepository, RepositoryStatus } from './repository';
import { CloudTrackerRepository } from './cloud';
import { getTrackerDatabase, read, write, scopeKey } from './storage';
import { CloudImportReview } from './ImportReview';
import { updateAvailable$, updateApp } from '../pwa';
import { Snapshot, Command, Outcome } from './model';
import { legacyBackup, parseBackup, downloadBackup } from './migration';
const MODE = 'tracker_mode_v3';
const DEVICE = 'tracker_device_v3';
const CONFIG = 'tracker_cloud_config_v3';
function cloudConfig() { try {
    return JSON.parse(localStorage.getItem(CONFIG) ?? 'null') ?? { url: SUPABASE_URL, key: SUPABASE_KEY };
}
catch {
    return { url: SUPABASE_URL, key: SUPABASE_KEY };
} }
export const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL || '';
export const SUPABASE_KEY = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY || '';
interface Context {
    repository: TrackerRepository | null;
    snapshot: Snapshot | null;
    status: RepositoryStatus;
    mode: 'local' | 'cloud';
    setMode(mode: 'local' | 'cloud'): void;
    user: User | null;
    client: SupabaseClient | null;
    execute(input: Omit<Command, 'operationId' | 'deviceId' | 'issuedAt' | 'expectedStateVersion'> & {
        expectedStateVersion?: number;
    }): Promise<Outcome>;
    supabaseUrl: string;
    supabaseKey: string;
    configureCloud(url: string, key: string): void;
    busy: boolean;
    error: string | undefined;
    setError(error: string | undefined): void;
}
const idle: RepositoryStatus = { connection: 'local', pending: 0, confirmationPending: false, needsConfirmation: [] };
const TrackerContext = createContext<Context | null>(null);
export function TrackerProvider({ children }: {
    children: ReactNode;
}) {
    const [connectionSettings, setConnectionSettings] = useState(cloudConfig);
    const supabaseUrl = connectionSettings.url;
    const supabaseKey = connectionSettings.key;
    const configureCloud = (url: string, key: string) => { const config = { url: new URL(url).origin, key }; localStorage.setItem(CONFIG, JSON.stringify(config)); setConnectionSettings(config); };
    const [mode, setModeState] = useState<'local' | 'cloud'>(() => localStorage.getItem(MODE) === 'cloud' ? 'cloud' : 'local');
    const [repository, setRepository] = useState<TrackerRepository | null>(null);
    const [snapshot, setSnapshot] = useState<Snapshot | null>(null);
    const [status, setStatus] = useState(idle);
    const [user, setUser] = useState<User | null>(null);
    const [client, setClient] = useState<SupabaseClient | null>(null);
    const [error, setError] = useState<string>();
    const [busy, setBusy] = useState(false);
    const busyRef = useRef(false);
    const deviceId = useRef(localStorage.getItem(DEVICE) || crypto.randomUUID());
    useEffect(() => { localStorage.setItem(DEVICE, deviceId.current); }, []);
    useEffect(() => {
        if (mode !== 'cloud' || !supabaseUrl || !supabaseKey) {
            setClient(null);
            setUser(null);
            return;
        }
        const c = createClient(supabaseUrl, supabaseKey);
        setClient(c);
        let alive = true;
        const { data: { subscription } } = c.auth.onAuthStateChange((_event, session) => { if (alive)
            setUser(session?.user ?? null); });
        void c.auth.getSession().then(({ data, error }) => { if (alive) {
            if (error)
                setError(error.message);
            setUser(data.session?.user ?? null);
        } });
        return () => { alive = false; subscription.unsubscribe(); void c.removeAllChannels(); c.auth.stopAutoRefresh(); };
    }, [mode, supabaseUrl, supabaseKey]);
    useEffect(() => {
        let alive = true;
        let repo: TrackerRepository | undefined;
        const subs: {
            unsubscribe(): void;
        }[] = [];
        setRepository(null);
        setSnapshot(null);
        setError(undefined);
        setStatus({ ...idle, connection: mode === 'local' ? 'local' : 'connecting' });
        void (async () => {
            const db = await getTrackerDatabase();
            if (!alive)
                return;
            if (mode === 'local') {
                repo = new LocalTrackerRepository(db, async () => {
                    const reviewed = await read<Snapshot>(db, 'local:migration-reviewed');
                    if (reviewed)
                        return parseBackup({ version: 3, snapshot: reviewed });
                    let preserved = await read<unknown>(db, 'legacy:backup');
                    if (!preserved) {
                        preserved = await legacyBackup(await getDatabase());
                        await write(db, 'legacy:backup', 'legacy', 'backup', preserved);
                    }
                    return parseBackup(preserved);
                });
            }
            else if (client && user)
                repo = new CloudTrackerRepository(db, client, await scopeKey(supabaseUrl, user.id), user.id);
            if (!repo || !alive)
                return;
            subs.push(repo.snapshot$.subscribe(s => { if (alive)
                setSnapshot(s); }), repo.status$.subscribe(s => { if (alive) {
                setStatus(s);
                if (s.error)
                    setError(s.error);
            } }));
            setRepository(repo);
            await (repo as LocalTrackerRepository | CloudTrackerRepository).initialize();
            if (!alive)
                repo.close();
        })().catch(e => { if (alive)
            setError(e.message); });
        return () => { alive = false; repo?.close(); subs.forEach(s => s.unsubscribe()); };
    }, [mode, client, user?.id]);
    const setMode = (next: 'local' | 'cloud') => { localStorage.setItem(MODE, next); setModeState(next); };
    const execute: Context['execute'] = async (input) => {
        if (!repository || !snapshot)
            throw new Error('Tracker is not ready');
        if (busyRef.current || status.pending)
            throw new Error('Wait for the pending operation');
        busyRef.current = true;
        setBusy(true);
        setError(undefined);
        try {
            const now = new Date().toISOString();
            const command: Command = { operationId: crypto.randomUUID(), deviceId: deviceId.current, issuedAt: now, expectedStateVersion: snapshot.state.version, ...input };
            const outcome = await repository.execute(command);
            if (outcome.status === 'conflict' || outcome.status === 'rejected')
                throw new Error(outcome.message ?? outcome.status);
            return outcome;
        }
        catch (e) {
            setError((e as Error).message);
            throw e;
        }
        finally {
            busyRef.current = false;
            setBusy(false);
        }
    };
    const value = { supabaseUrl, supabaseKey, configureCloud, repository, snapshot, status, mode, setMode, user, client, execute, busy, error, setError };
    return <TrackerContext.Provider value={value}>{children}</TrackerContext.Provider>;
}
export function useTracker() { const c = useContext(TrackerContext); if (!c)
    throw new Error('TrackerProvider missing'); return c; }
export function TrackerStatus() {
    const { snapshot, status, mode, repository, execute, error, setError, busy } = useTracker();
    const [updateAvailable, setUpdateAvailable] = useState(updateAvailable$.value);
    useEffect(() => { const sub = updateAvailable$.subscribe(setUpdateAvailable); return () => sub.unsubscribe(); }, []);
    const conflicts = Object.values(snapshot?.conflicts ?? {}).filter(f => !f.resolved);
    const run = (action: () => Promise<unknown>) => { void action().catch(e => setError(e.message)); };
    return <Box sx={{ px: 2, py: 1 }}>
    <CloudImportReview />
    <Typography variant="caption">{mode === 'local' ? 'Local · available offline' : `Cloud · ${status.connection}`} · {status.pending} pending · {conflicts.length} conflicts{status.lastRefresh ? ` · Refreshed ${new Date(status.lastRefresh).toLocaleTimeString()}` : ''}</Typography>
    {updateAvailable && <Alert severity="info">An app update is ready. Save your drafts before reloading.<Button disabled={busy || status.pending > 0} onClick={() => void updateApp(true)}>Update and reload</Button></Alert>}
    {(busy || status.pending > 0) && <Alert severity="info">{status.confirmationPending ? 'Confirmation pending. The request has not been cancelled.' : 'Saving…'}</Alert>}
    {error && <Alert severity="error" onClose={() => setError(undefined)}>{error} <Button onClick={() => run(async () => { await repository?.refresh(); })}>Reload</Button></Alert>}
    {status.needsConfirmation.map(c => <Alert severity="warning" key={c.operationId}>Unconfirmed {c.type}: {snapshot?.records.projects[c.projectId ?? '']?.data.name ?? c.projectId} requested at {new Date(c.intendedAt).toLocaleString()}. Resubmitting keeps this requested time.<Button onClick={() => run(() => (repository as CloudTrackerRepository).confirmResubmit(c.operationId))}>Confirm resubmission</Button></Alert>)}
    {conflicts.map(f => <Alert key={f.id} severity="warning">
      Current: {snapshot?.records.projects[snapshot.state.activeSessionId ? snapshot.records.timeEntries[snapshot.state.activeSessionId]?.data.projectId : '']?.data.name ?? 'Idle'} · {snapshot?.state.activeSessionId ? snapshot.records.timeEntries[snapshot.state.activeSessionId]?.data.startTime : ''}. Requested: {snapshot?.records.projects[f.command.projectId ?? '']?.data.name ?? f.command.type} at {new Date(f.command.intendedAt).toLocaleString()}.
      <Button disabled={busy} onClick={() => run(async () => { await execute({ type: 'resolve', intendedAt: new Date().toISOString(), conflictId: f.id, expectedConflictVersion: f.version, resolution: 'keep' }); })}>Keep current</Button>
      {['start', 'switch', 'break', 'resume'].includes(f.command.type) && <Button disabled={busy} onClick={() => run(async () => { await execute({ type: 'resolve', intendedAt: new Date().toISOString(), conflictId: f.id, expectedConflictVersion: f.version, resolution: 'switch' }); })}>Switch now</Button>}
      {f.command.type === 'edit' && <details><summary>Review and reapply draft</summary><pre style={{ whiteSpace: 'pre-wrap' }}>{JSON.stringify(f.command.mutations?.map(m => ({ entity: m.entity, id: m.id, current: snapshot?.records[m.entity][m.id]?.data, requested: m.data })), null, 2)}</pre><Button disabled={busy} onClick={() => run(async () => { await execute({ type: 'edit', intendedAt: new Date().toISOString(), conflictId: f.id, expectedConflictVersion: f.version, mutations: f.command.mutations?.map(m => ({ ...m, expectedVersion: snapshot?.records[m.entity][m.id]?.version ?? 0 })) }); })}>Reapply reviewed draft</Button></details>}
      <Button onClick={() => downloadBackup(f.command, 'conflicting-request.json')}>Export draft</Button>
    </Alert>)}
  </Box>;
}
export function TrackerGate({ children }: {
    children: ReactNode;
}) {
    const { snapshot, mode, setMode, client, user, error, setError } = useTracker();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [migrationReview, setMigrationReview] = useState<Snapshot>();
    if (snapshot)
        return <>{children}</>;
    const auth = async (signup = false) => { if (!client)
        return; const result = signup ? await client.auth.signUp({ email, password }) : await client.auth.signInWithPassword({ email, password }); if (result.error)
        setError(result.error.message);
    else if (signup && !result.data.session)
        setError('Check your email to confirm your account.'); };
    return <Box sx={{ p: 3 }}><Typography variant="h5">Time Tracker</Typography><TrackerStatus />
    {mode === 'cloud' && !user && <><Typography>{client ? 'Sign in to your cloud account.' : 'Cloud requires VITE_SUPABASE_URL and VITE_SUPABASE_PUBLISHABLE_KEY.'}</Typography><input aria-label="Email" type="email" value={email} onChange={e => setEmail(e.target.value)}/><input aria-label="Password" type="password" value={password} onChange={e => setPassword(e.target.value)}/><Button onClick={() => void auth()}>Sign in</Button><Button onClick={() => void auth(true)}>Sign up</Button></>}
    {!error && mode === 'local' && <Typography>Opening local data and recovering interrupted operations…</Typography>}
    <Button onClick={() => setMode(mode === 'local' ? 'cloud' : 'local')}>Use {mode === 'local' ? 'Cloud' : 'Local'}</Button>
    {mode === 'local' && error && <Box><Typography>Migration needs review. Export the preserved data, correct conflicting sessions explicitly, then select the corrected backup.</Typography><input type="file" aria-label="Corrected migration backup" accept=".json" onChange={e => { const file = e.target.files?.[0]; if (file)
        void file.text().then(text => setMigrationReview(parseBackup(JSON.parse(text)))).catch(e => setError(e.message)); }}/>{migrationReview && <><pre>{JSON.stringify({ projects: Object.keys(migrationReview.records.projects).length, sessions: Object.keys(migrationReview.records.timeEntries).length, activeSessionId: migrationReview.state.activeSessionId }, null, 2)}</pre><Button onClick={() => void getTrackerDatabase().then(db => write(db, 'local:migration-reviewed', 'local', 'migration', migrationReview)).then(() => window.location.reload()).catch(e => setError(e.message))}>Use reviewed migration</Button></>}</Box>}
    <Button onClick={() => void exportRecovery().catch(e => setError(e.message))}>Export preserved data</Button>
  </Box>;
}
export async function exportRecovery() {
    const db = await getTrackerDatabase();
    const preserved = await read(db, 'legacy:backup');
    if (preserved) {
        downloadBackup(preserved, 'preserved-local-data.json');
        return;
    }
    // Read raw stores even when RxDB cannot open a mismatched schema. No reset.
    const exported: Record<string, unknown> = {};
    for (const info of await indexedDB.databases()) {
        if (!info.name?.includes('timetracker'))
            continue;
        const name = info.name;
        exported[name] = await new Promise((resolve, reject) => { const req = indexedDB.open(name); req.onerror = () => reject(req.error); req.onsuccess = () => { const raw = req.result; const result: Record<string, unknown> = {}; const names = Array.from(raw.objectStoreNames); if (!names.length) {
            raw.close();
            resolve(result);
            return;
        } const tx = raw.transaction(names, 'readonly'); for (const store of names) {
            const r = tx.objectStore(store).getAll();
            r.onsuccess = () => { result[store] = r.result; };
        } tx.oncomplete = () => { raw.close(); resolve(result); }; tx.onerror = () => { raw.close(); reject(tx.error); }; }; });
    }
    downloadBackup({ format: 'raw-indexeddb-recovery', databases: exported }, 'indexeddb-recovery.json');
}
