/**
 * Pure overlap resolution logic for time entries.
 * Takes existing entries + a new time range and returns a list of operations
 * (update/delete/split) without executing them.
 */

export interface OverlapEntry {
  id: string;
  projectId: string;
  startTime: Date;
  endTime?: Date;
  description?: string;
}

export interface OverlapUpdate {
  type: 'update';
  entryId: string;
  updates: {
    startTime?: Date;
    endTime?: Date;
    duration: number;
  };
}

export interface OverlapDelete {
  type: 'delete';
  entryId: string;
}

export interface OverlapSplit {
  type: 'split_create';
  projectId: string;
  startTime: Date;
  endTime: Date;
  duration: number;
  description?: string;
}

export type OverlapOperation = OverlapUpdate | OverlapDelete | OverlapSplit;

export interface OverlapResult {
  operations: OverlapOperation[];
  affectedProjectIds: string[];
}

export function resolveOverlaps(
  existingEntries: OverlapEntry[],
  newStart: Date,
  newEnd: Date
): OverlapResult {
  const newStartMs = newStart.getTime();
  const newEndMs = newEnd.getTime();
  const operations: OverlapOperation[] = [];
  const affectedProjectIds = new Set<string>();

  for (const entry of existingEntries) {
    // Skip entries without endTime (actively tracking)
    if (!entry.endTime) continue;

    const eStart = entry.startTime.getTime();
    const eEnd = entry.endTime.getTime();

    // Check for any overlap
    if (!(eStart < newEndMs && eEnd > newStartMs)) continue;

    affectedProjectIds.add(entry.projectId);

    if (eStart < newStartMs && eEnd > newEndMs) {
      // Entry completely contains the new entry - split it
      // Trim original to end at new start
      operations.push({
        type: 'update',
        entryId: entry.id,
        updates: {
          endTime: newStart,
          duration: newStartMs - eStart,
        },
      });
      // Create second part after new entry
      operations.push({
        type: 'split_create',
        projectId: entry.projectId,
        startTime: newEnd,
        endTime: entry.endTime,
        duration: eEnd - newEndMs,
        description: entry.description,
      });
    } else if (eStart < newStartMs && eEnd > newStartMs) {
      // Entry overlaps at the beginning - trim end
      operations.push({
        type: 'update',
        entryId: entry.id,
        updates: {
          endTime: newStart,
          duration: newStartMs - eStart,
        },
      });
    } else if (eStart < newEndMs && eEnd > newEndMs) {
      // Entry overlaps at the end - trim start
      operations.push({
        type: 'update',
        entryId: entry.id,
        updates: {
          startTime: newEnd,
          duration: eEnd - newEndMs,
        },
      });
    } else if (eStart >= newStartMs && eEnd <= newEndMs) {
      // Entry is completely contained - delete it
      operations.push({
        type: 'delete',
        entryId: entry.id,
      });
    }
  }

  return {
    operations,
    affectedProjectIds: Array.from(affectedProjectIds),
  };
}
