import { useState } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  ToggleButton,
  ToggleButtonGroup,
  Box,
  Typography,
} from '@mui/material';
import { DateTimePicker } from '@mui/x-date-pickers/DateTimePicker';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { AdapterDateFns } from '@mui/x-date-pickers/AdapterDateFns';
import { de } from 'date-fns/locale/de';

interface RetroactiveStartDialogProps {
  open: boolean;
  projectName: string;
  projectIcon: string;
  onClose: () => void;
  onConfirm: (startTime: Date) => void;
}

type QuickOption = 'now' | '5min' | '10min' | '15min' | '30min' | '1hour' | '2hours' | 'custom';

export function RetroactiveStartDialog({
  open,
  projectName,
  projectIcon,
  onClose,
  onConfirm,
}: RetroactiveStartDialogProps) {
  const [selectedOption, setSelectedOption] = useState<QuickOption>('now');
  const [customTime, setCustomTime] = useState<Date | null>(new Date());

  const handleOptionChange = (_: React.MouseEvent<HTMLElement>, newOption: QuickOption | null) => {
    if (newOption) {
      setSelectedOption(newOption);
    }
  };

  const calculateStartTime = (): Date => {
    const now = new Date();

    switch (selectedOption) {
      case 'now':
        return now;
      case '5min':
        return new Date(now.getTime() - 5 * 60 * 1000);
      case '10min':
        return new Date(now.getTime() - 10 * 60 * 1000);
      case '15min':
        return new Date(now.getTime() - 15 * 60 * 1000);
      case '30min':
        return new Date(now.getTime() - 30 * 60 * 1000);
      case '1hour':
        return new Date(now.getTime() - 60 * 60 * 1000);
      case '2hours':
        return new Date(now.getTime() - 2 * 60 * 60 * 1000);
      case 'custom':
        if (customTime) {
          // DateTimePicker provides full datetime, validate it's not in future
          if (customTime > now) return now;
          return customTime;
        }
        return now;
      default:
        return now;
    }
  };

  const [submitting,setSubmitting] = useState(false);
  const handleConfirm = async () => {
    if(submitting)return;
    setSubmitting(true);
    try {
    await onConfirm(calculateStartTime());
    setSelectedOption('now');
    setCustomTime(new Date());
    } catch { /* Keep the draft; repository status displays the failure. */ } finally {setSubmitting(false);}
  };

  const handleClose = () => {
    onClose();
    setSelectedOption('now');
    setCustomTime(new Date());
  };

  return (
    <LocalizationProvider dateAdapter={AdapterDateFns} adapterLocale={de}>
      <Dialog open={open} onClose={handleClose} maxWidth="xs" fullWidth>
        <DialogTitle>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <span style={{ fontSize: '1.5rem' }}>{projectIcon}</span>
            <span>Start {projectName}</span>
          </Box>
        </DialogTitle>
        <DialogContent>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            When did you actually start?
          </Typography>

          <ToggleButtonGroup
            value={selectedOption}
            exclusive
            onChange={handleOptionChange}
            aria-label="start time option"
            sx={{
              display: 'flex',
              flexWrap: 'wrap',
              gap: 1,
              '& .MuiToggleButton-root': {
                flex: '1 1 auto',
                minWidth: '80px',
              }
            }}
          >
            <ToggleButton value="now">Now</ToggleButton>
            <ToggleButton value="5min">5 min ago</ToggleButton>
            <ToggleButton value="10min">10 min ago</ToggleButton>
            <ToggleButton value="15min">15 min ago</ToggleButton>
            <ToggleButton value="30min">30 min ago</ToggleButton>
            <ToggleButton value="1hour">1 hour ago</ToggleButton>
            <ToggleButton value="2hours">2 hours ago</ToggleButton>
            <ToggleButton value="custom">Custom</ToggleButton>
          </ToggleButtonGroup>

          {selectedOption === 'custom' && (
            <Box sx={{ mt: 2 }}>
              <DateTimePicker
                label="Start time"
                value={customTime}
                onChange={(newValue) => setCustomTime(newValue)}
                maxDateTime={new Date()}
                slotProps={{
                  textField: {
                    fullWidth: true,
                    size: 'small'
                  }
                }}
              />
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={handleClose}>Cancel</Button>
          <Button disabled={submitting} onClick={handleConfirm} variant="contained">
            Start
          </Button>
        </DialogActions>
      </Dialog>
    </LocalizationProvider>
  );
}
