import { RxJsonSchema } from 'rxdb';

export interface OvertimeAdjustmentDocument {
  id: string;
  userId?: string;
  date: string; // YYYY-MM-DD
  hours: number;
  reason?: string;
  updatedAt: string;
}

export const overtimeAdjustmentSchema: RxJsonSchema<OvertimeAdjustmentDocument> = {
  version: 1,
  title: 'overtime adjustment schema',
  primaryKey: 'id',
  type: 'object',
  properties: {
    id: {
      type: 'string',
      maxLength: 100,
    },
    userId: {
      type: 'string',
      maxLength: 100,
    },
    date: {
      type: 'string',
      maxLength: 10,
    },
    hours: {
      type: 'number',
    },
    reason: {
      type: 'string',
      maxLength: 500,
    },
    updatedAt: {
      type: 'string',
      format: 'date-time',
      maxLength: 30,
    },
  },
  required: ['id', 'date', 'hours', 'updatedAt'],
  indexes: [['date', 'updatedAt']],
};
