import React, { useState, useRef, useMemo } from 'react';
import {
  Card,
  CardContent,
  Typography,
  LinearProgress,
  Box,
  IconButton,
  Select,
  MenuItem,
} from '@mui/material';
import { styled } from '@mui/material/styles';
import DeleteIcon from '@mui/icons-material/Delete';
import EditIcon from '@mui/icons-material/Edit';
import { Project, TimeEntry, Settings } from '../types';
import { formatDuration, calculateMonthlyProgress, calculateMonthlyTargetHours, calculateTotalTimeForPeriod, getDurationInHours } from '../utils/timeUtils';

interface ProjectTileProps {
  project: Project;
  timeEntries: TimeEntry[];
  settings: Settings;
  onToggle: (projectId: string) => void;
  onDelete: (projectId: string) => void;
  onEdit: (project: Project) => void;
  onStartProject?: (projectId: string) => void;
  subProjects?: Project[];
  activeProjectId?: string | null;
}

const StyledCard = styled(Card)<{ isActive: boolean; projectColor: string; childActive?: boolean }>(
  ({ theme, isActive, projectColor, childActive }) => ({
    minHeight: 120,
    cursor: 'pointer',
    position: 'relative',
    border: isActive
      ? `3px solid ${projectColor}`
      : childActive
        ? `2px dashed ${projectColor}`
        : `1px solid ${theme.palette.divider}`,
    backgroundColor: isActive ? `${projectColor}20` : theme.palette.background.paper,
    transition: 'all 0.2s ease-in-out',
    '&:hover': {
      transform: 'translateY(-2px)',
      boxShadow: theme.shadows[4],
    },
  })
);

const IconContainer = styled(Box)({
  fontSize: '2rem',
  marginBottom: '8px',
  textAlign: 'center',
});

const DeleteButton = styled(IconButton)({
  position: 'absolute',
  top: 4,
  right: 4,
  opacity: 0,
  transition: 'opacity 0.3s ease',
});

const EditButton = styled(IconButton)({
  position: 'absolute',
  top: 4,
  left: 4, // Position in top left corner
  opacity: 0,
  transition: 'opacity 0.3s ease',
});

export const ProjectTile: React.FC<ProjectTileProps> = ({
  project,
  timeEntries,
  settings,
  onToggle,
  onDelete,
  onEdit,
  onStartProject,
  subProjects: childProjects,
  activeProjectId,
}) => {
  const [showDelete, setShowDelete] = useState(false);
  const [pressTimer, setPressTimer] = useState<NodeJS.Timeout | null>(null);
  const [touchHandled, setTouchHandled] = useState(false);
  const [buttonClicked, setButtonClicked] = useState(false);
  const [lastTap, setLastTap] = useState(0);
  const [singleTapTimer, setSingleTapTimer] = useState<NodeJS.Timeout | null>(null);
  const cardRef = useRef<HTMLDivElement>(null);
  const touchStartPos = useRef<{ x: number; y: number } | null>(null);
  const isScrolling = useRef(false);

  const hasChildren = childProjects && childProjects.length > 0;
  const childActive = hasChildren && childProjects.some(c => c.id === activeProjectId);

  // Compute progress; special-case the aggregate "Work" project
  const { displayTotalMs, progressToShow } = useMemo(() => {
    const now = new Date();
    const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
    const endOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0);

    let totalMs = project.totalTime;
    let progress = 0;

    if (project.id === 'work') {
      // Aggregate totals across all non-break entries
      totalMs = timeEntries
        .filter((e) => e.endTime && e.projectId !== 'break')
        .reduce((sum, e) => sum + e.duration, 0);

      const monthlyTotalTime = calculateTotalTimeForPeriod(
        timeEntries.filter((e) => e.projectId !== 'break'),
        startOfMonth,
        endOfMonth
      );
      const monthlyTargetHours = calculateMonthlyTargetHours(now, settings);
      const monthlyTotalHours = monthlyTotalTime / (1000 * 60 * 60);
      progress = monthlyTargetHours > 0 ? (monthlyTotalHours / monthlyTargetHours) * 100 : 0;
    } else {
      progress = calculateMonthlyProgress(project, timeEntries, settings);
    }

    return { displayTotalMs: totalMs, progressToShow: progress };
  }, [project, timeEntries, settings]);

  const handleMouseDown = () => {
    if (touchHandled || buttonClicked) return;
    const timer = setTimeout(() => {
      setShowDelete(true);
    }, 1000);
    setPressTimer(timer);
  };

  const handleMouseUp = () => {
    if (touchHandled) {
      setTouchHandled(false);
      return;
    }
    if (buttonClicked) {
      return;
    }
    if (pressTimer) {
      clearTimeout(pressTimer);
      setPressTimer(null);
    }
    if (!showDelete) {
      // Use immediate toggle for mouse to maintain responsive feel
      onToggle(project.id);
    }
  };

  const handleMouseLeave = () => {
    if (pressTimer) {
      clearTimeout(pressTimer);
      setPressTimer(null);
    }
    if (singleTapTimer) {
      clearTimeout(singleTapTimer);
      setSingleTapTimer(null);
    }
    setShowDelete(false);
  };

  const handleTouchStart = (e: React.TouchEvent) => {
    setTouchHandled(true);
    isScrolling.current = false;
    touchStartPos.current = { x: e.touches[0].clientX, y: e.touches[0].clientY };
    const timer = setTimeout(() => {
      setShowDelete(true);
    }, 1000);
    setPressTimer(timer);
  };

  const handleTouchMove = (e: React.TouchEvent) => {
    if (!touchStartPos.current) return;

    const deltaX = Math.abs(e.touches[0].clientX - touchStartPos.current.x);
    const deltaY = Math.abs(e.touches[0].clientY - touchStartPos.current.y);

    if (deltaX > 10 || deltaY > 10) {
      isScrolling.current = true;
      if (pressTimer) {
        clearTimeout(pressTimer);
        setPressTimer(null);
      }
    }
  };

  const handleTouchEnd = (e: React.TouchEvent) => {
    if (pressTimer) {
      clearTimeout(pressTimer);
      setPressTimer(null);
    }

    if (isScrolling.current) {
      isScrolling.current = false;
      touchStartPos.current = null;
      if (showDelete) {
        setTimeout(() => setShowDelete(false), 200);
      }
      return;
    }

    e.preventDefault(); // Prevent mouse events from firing on tap

    if (!buttonClicked) {
      const now = Date.now();
      if (now - lastTap < 300) {
        // Double tap detected - clear single tap timer and open edit dialog
        if (singleTapTimer) {
          clearTimeout(singleTapTimer);
          setSingleTapTimer(null);
        }
        onEdit(project);
        setLastTap(0);
      } else {
        // Potential single tap - wait to see if double tap follows
        setLastTap(now);
        if (!showDelete) {
          const timer = setTimeout(() => {
            onToggle(project.id);
            setSingleTapTimer(null);
          }, 300);
          setSingleTapTimer(timer);
        }
      }
    }

    // Reset button clicked flag after a short delay
    setTimeout(() => setButtonClicked(false), 100);
  };

  const handleDelete = (e: React.MouseEvent | React.TouchEvent) => {
    e.stopPropagation();
    e.preventDefault();
    setButtonClicked(true);
    onDelete(project.id);
    setShowDelete(false);
  };

  const handleEdit = (e: React.MouseEvent | React.TouchEvent) => {
    e.stopPropagation();
    e.preventDefault();
    setButtonClicked(true);
    onEdit(project);
    setShowDelete(false);
  };

  return (
    <StyledCard
      ref={cardRef}
      isActive={project.isActive}
      projectColor={project.color}
      childActive={childActive}
      role="button"
      tabIndex={0}
      aria-label={`${project.name} — ${project.isActive ? 'active' : 'inactive'}`}
      onKeyDown={(e: React.KeyboardEvent) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onToggle(project.id);
        }
      }}
      onMouseDown={handleMouseDown}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseLeave}
      onTouchStart={handleTouchStart}
      onTouchMove={handleTouchMove}
      onTouchEnd={handleTouchEnd}
    >
      <CardContent sx={{ textAlign: 'center', position: 'relative' }}>
        {showDelete && project.id !== 'work' && (
          <>
            <EditButton
              onClick={handleEdit}
              onTouchStart={(e) => {
                e.stopPropagation();
                setButtonClicked(true);
              }}
              onTouchEnd={handleEdit}
              sx={{ opacity: 1 }}
              color="primary"
              aria-label={`Edit ${project.name}`}
            >
              <EditIcon />
            </EditButton>
            <DeleteButton
              onClick={handleDelete}
              onTouchStart={(e) => {
                e.stopPropagation();
                setButtonClicked(true);
              }}
              onTouchEnd={handleDelete}
              sx={{ opacity: 1 }}
              color="error"
              aria-label={`Delete ${project.name}`}
            >
              <DeleteIcon />
            </DeleteButton>
          </>
        )}

        <IconContainer>{project.icon}</IconContainer>

        <Typography variant="h6" component="h2" gutterBottom>
          {project.name}
        </Typography>

        <Typography variant="body2" color="text.secondary" gutterBottom>
          {formatDuration(displayTotalMs)}
        </Typography>

        {project.budgetHours != null && project.budgetHours > 0 && (
          <Typography variant="caption" color="text.secondary" display="block" gutterBottom>
            Budget: {Math.max(0, project.budgetHours - getDurationInHours(displayTotalMs)).toFixed(1)}h left / {project.budgetHours}h
            {project.budgetDeadline && ` (until ${project.budgetDeadline})`}
          </Typography>
        )}

    {project.id !== 'break' && (
          <Box sx={{ mt: 2 }}>
            <Typography variant="caption" display="block" gutterBottom>
      Monthly Progress: {progressToShow.toFixed(1)}%
            </Typography>
            <LinearProgress
              variant="determinate"
      value={Math.min(progressToShow, 100)}
              sx={{
                height: 6,
                borderRadius: 3,
                backgroundColor: 'rgba(0, 0, 0, 0.1)',
                '& .MuiLinearProgress-bar': {
                  backgroundColor: project.color,
                },
              }}
            />
          </Box>
        )}

        {/* Sub-project dropdown */}
        {hasChildren && (
          <Box
            sx={{ mt: 1.5 }}
            onMouseDown={(e) => e.stopPropagation()}
            onMouseUp={(e) => e.stopPropagation()}
            onTouchStart={(e) => e.stopPropagation()}
            onTouchEnd={(e) => e.stopPropagation()}
            onClick={(e) => e.stopPropagation()}
          >
            <Select
              size="small"
              displayEmpty
              value={childProjects.find(c => c.id === activeProjectId)?.id ?? ''}
              onChange={(e) => {
                const val = e.target.value;
                if (val === '__parent__') {
                  // Atomically switch from active child to parent
                  if (onStartProject) {
                    onStartProject(project.id);
                  }
                } else if (val) {
                  onToggle(val);
                }
              }}
              fullWidth
              sx={{ fontSize: '0.75rem', '.MuiSelect-select': { py: 0.5 } }}
              renderValue={(selected) => {
                if (!selected) return <em>Sub-projects...</em>;
                const child = childProjects.find(c => c.id === selected);
                return child ? `${child.icon} ${child.name}` : <em>Sub-projects...</em>;
              }}
            >
              {childActive && (
                <MenuItem value="__parent__" sx={{ fontSize: '0.8rem', fontStyle: 'italic' }}>
                  Parent only ({project.name})
                </MenuItem>
              )}
              {childProjects.map((child) => (
                <MenuItem key={child.id} value={child.id} sx={{ fontSize: '0.8rem' }}>
                  <Box sx={{ display: 'flex', justifyContent: 'space-between', width: '100%', gap: 1 }}>
                    <span>{child.icon} {child.name}</span>
                    <Typography variant="caption" color="text.secondary">
                      {formatDuration(child.totalTime)}
                    </Typography>
                  </Box>
                </MenuItem>
              ))}
            </Select>
          </Box>
        )}
      </CardContent>
    </StyledCard>
  );
};
