import React, { useState } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Button,
  Box,
  Typography,
  IconButton,
  FormControl,
  FormLabel,
  RadioGroup,
  FormControlLabel,
  Radio,
  Select,
  MenuItem,
  InputLabel
} from '@mui/material';
import { TargetType, Project } from '../types';

interface AddProjectDialogProps {
  open: boolean;
  onClose: () => void;
  onAdd: (project: {
    name: string;
    icon: string;
    color: string;
    targetType: TargetType;
    targetValue?: number;
    initialHours?: number;
    budgetHours?: number;
    budgetDeadline?: string;
    parentId?: string;
  }) => void;
  availableParents?: Project[];
}



const COMMON_EMOJIS = ['💼', '📊', '🔬', '🎨', '📝', '📞', '🏠', '🚗', '🏋️', '📚', '🛒', '🍳', '⚽', '🎵', '💻', '🌟', '🔥', '💡', '🎯', '🏆', '📱', '⌚', '🎮', '📷', '✈️', '🍕', '☕', '🌍', '❤️', '🚀'];

const getRandomEmoji = () => COMMON_EMOJIS[Math.floor(Math.random() * COMMON_EMOJIS.length)];
const getRandomColor = () => '#' + Math.floor(Math.random()*16777215).toString(16).padStart(6, '0');

export const AddProjectDialog: React.FC<AddProjectDialogProps> = ({ open, onClose, onAdd, availableParents = [] }) => {
  const [name, setName] = useState('');
  const [selectedIcon, setSelectedIcon] = useState('');
  const [customIcon, setCustomIcon] = useState('');
  const [selectedColor, setSelectedColor] = useState('');
  const [targetType, setTargetType] = useState<TargetType>('none');
  const [targetValue, setTargetValue] = useState<string>('');
  const [initialHours, setInitialHours] = useState<string>('');
  const [budgetHours, setBudgetHours] = useState<string>('');
  const [budgetDeadline, setBudgetDeadline] = useState<string>('');
  const [parentId, setParentId] = useState<string>('');

  // Initialize with random values when dialog opens
  React.useEffect(() => {
    if (open && !selectedIcon && !selectedColor) {
      setSelectedIcon(getRandomEmoji());
      setSelectedColor(getRandomColor());
    }
  }, [open, selectedIcon, selectedColor]);

  const [submitting,setSubmitting] = React.useState(false);
  const handleSubmit = async () => {
    if(submitting)return;
    setSubmitting(true);
    try {
    if (name.trim()) {
      const finalIcon = customIcon.trim() || selectedIcon;
      await onAdd({
        name: name.trim(),
        icon: finalIcon,
        color: selectedColor,
        targetType,
        targetValue: targetType !== 'none' && targetValue ? parseFloat(targetValue) : undefined,
        initialHours: initialHours ? parseFloat(initialHours) : undefined,
        budgetHours: budgetHours ? parseFloat(budgetHours) : undefined,
        budgetDeadline: budgetDeadline || undefined,
        parentId: parentId || undefined,
      });
      handleClose();
    }
    } catch { /* Keep the draft; repository status displays the failure. */ } finally {setSubmitting(false);}
  };

  const handleClose = () => {
    setName('');
    setSelectedIcon('');
    setCustomIcon('');
    setSelectedColor('');
    setTargetType('none');
    setTargetValue('');
    setInitialHours('');
    setBudgetHours('');
    setBudgetDeadline('');
    setParentId('');
    onClose();
  };

  const handleRandomize = () => {
    setSelectedIcon(getRandomEmoji());
    setSelectedColor(getRandomColor());
    setCustomIcon('');
  };

  return (
    <Dialog open={open} onClose={handleClose} maxWidth="sm" fullWidth>
      <DialogTitle>Add New Project</DialogTitle>
      <DialogContent>
        <TextField
          autoFocus
          margin="dense"
          label="Project Name"
          fullWidth
          variant="outlined"
          value={name}
          onChange={(e) => setName(e.target.value)}
          sx={{ mb: 3 }}
        />

        {availableParents.length > 0 && (
          <FormControl fullWidth margin="dense" sx={{ mb: 2 }}>
            <InputLabel id="parent-project-label">Parent Project (optional)</InputLabel>
            <Select
              labelId="parent-project-label"
              value={parentId}
              label="Parent Project (optional)"
              onChange={(e) => setParentId(e.target.value)}
            >
              <MenuItem value="">
                <em>None (top-level project)</em>
              </MenuItem>
              {availableParents.map((p) => (
                <MenuItem key={p.id} value={p.id}>
                  {p.icon} {p.name}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
        )}

        <Box sx={{ mb: 3 }}>
          <FormControl component="fieldset">
            <FormLabel component="legend">Monthly Target (optional)</FormLabel>
            <RadioGroup
              value={targetType}
              onChange={(e) => setTargetType(e.target.value as TargetType)}
              row
            >
              <FormControlLabel value="none" control={<Radio />} label="No Target" />
              <FormControlLabel value="hours" control={<Radio />} label="Hours" />
              <FormControlLabel value="percentage" control={<Radio />} label="Percentage" />
            </RadioGroup>
          </FormControl>
          
          {targetType !== 'none' && (
            <TextField
              margin="normal"
              label={targetType === 'hours' ? 'Target Hours per Month' : 'Target Percentage'}
              type="number"
              fullWidth
              variant="outlined"
              value={targetValue}
              onChange={(e) => setTargetValue(e.target.value)}
              inputProps={{ 
                min: 0, 
                max: targetType === 'percentage' ? 100 : undefined,
                step: targetType === 'percentage' ? 1 : 0.5 
              }}
              helperText={targetType === 'hours' ? 'Total hours to work on this project per month' : 'Percentage of total work time for this project (0-100%)'}
            />
          )}
        </Box>
        
        <TextField
          margin="dense"
          label="Initial Hours (optional)"
          type="number"
          fullWidth
          variant="outlined"
          value={initialHours}
          onChange={(e) => setInitialHours(e.target.value)}
          inputProps={{ min: 0, step: 0.5 }}
          helperText="Hours already worked on this project this month (useful when starting mid-month)"
          sx={{ mb: 3 }}
        />

        <Box sx={{ mb: 3, p: 2, border: '1px solid', borderColor: 'divider', borderRadius: 1 }}>
          <Typography variant="subtitle2" gutterBottom>
            Hour Budget (optional)
          </Typography>
          <TextField
            margin="dense"
            label="Total Budget Hours"
            type="number"
            fullWidth
            variant="outlined"
            value={budgetHours}
            onChange={(e) => setBudgetHours(e.target.value)}
            inputProps={{ min: 0, step: 0.5 }}
            helperText="Total hours allocated for this project"
            sx={{ mb: 1 }}
          />
          <TextField
            margin="dense"
            label="Deadline"
            type="date"
            fullWidth
            variant="outlined"
            value={budgetDeadline}
            onChange={(e) => setBudgetDeadline(e.target.value)}
            slotProps={{ inputLabel: { shrink: true } }}
            helperText="Budget deadline date"
          />
        </Box>

        <Typography variant="h6" gutterBottom>
          Project Icon
        </Typography>
        
        <Box sx={{ display: 'flex', gap: 2, alignItems: 'center', mb: 2 }}>
          <Box sx={{ 
            width: 64, 
            height: 64, 
            display: 'flex', 
            alignItems: 'center', 
            justifyContent: 'center',
            border: '2px solid',
            borderColor: 'primary.main',
            borderRadius: 1,
            backgroundColor: selectedColor,
            color: 'white',
            fontSize: '2rem'
          }}>
            {customIcon || selectedIcon}
          </Box>
          <Button variant="outlined" onClick={handleRandomize} size="small">
            🎲 Randomize
          </Button>
        </Box>

        <TextField
          label="Custom Emoji (or use suggestions below)"
          value={customIcon}
          onChange={(e) => {
            setCustomIcon(e.target.value);
            setSelectedIcon(''); // Clear selected when typing custom
          }}
          fullWidth
          margin="normal"
          helperText="Type any emoji or leave empty to use suggestions"
          sx={{ mb: 2 }}
        />

        <Typography variant="body2" gutterBottom>
          Quick suggestions:
        </Typography>
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mb: 3 }}>
          {COMMON_EMOJIS.slice(0, 15).map((emoji) => (
            <IconButton
              key={emoji}
              onClick={() => {
                setSelectedIcon(emoji);
                setCustomIcon('');
              }}
              sx={{ 
                width: 40, 
                height: 40,
                border: selectedIcon === emoji ? '2px solid' : '1px solid transparent',
                borderColor: selectedIcon === emoji ? 'primary.main' : 'transparent'
              }}
            >
              <Typography variant="body1">{emoji}</Typography>
            </IconButton>
          ))}
        </Box>

        <Typography variant="h6" gutterBottom>
          Project Color
        </Typography>
        <Box sx={{ display: 'flex', gap: 2, alignItems: 'center', mb: 2 }}>
          <input
            type="color"
            value={selectedColor}
            onChange={(e) => setSelectedColor(e.target.value)}
            style={{
              width: '60px',
              height: '40px',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer'
            }}
          />
          <Typography variant="body2" color="text.secondary">
            {selectedColor}
          </Typography>
          <Button 
            variant="text" 
            size="small" 
            onClick={() => setSelectedColor(getRandomColor())}
          >
            Random Color
          </Button>
        </Box>
      </DialogContent>
      <DialogActions>
        <Button onClick={handleClose}>Cancel</Button>
        <Button 
          onClick={handleSubmit} 
          variant="contained"
          disabled={submitting || (!name.trim())}
        >
          Add Project
        </Button>
      </DialogActions>
    </Dialog>
  );
};