import { useState } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  ToggleButton,
  ToggleButtonGroup,
  Box,
  Typography,
} from '@mui/material';
import { DateTimePicker } from '@mui/x-date-pickers/DateTimePicker';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { AdapterDateFns } from '@mui/x-date-pickers/AdapterDateFns';
import { de } from 'date-fns/locale/de';

interface ForgotToStopDialogProps {
  open: boolean;
  projectName: string;
  sessionStart: Date;
  onClose: () => void;
  onConfirm: (endTime: Date) => void;
  onStopNow: () => void;
}

type QuickOption = '30min' | '1hour' | '2hours' | 'custom' | 'now';

export function ForgotToStopDialog({
  open,
  projectName,
  sessionStart,
  onClose,
  onConfirm,
  onStopNow,
}: ForgotToStopDialogProps) {
  const [selectedOption, setSelectedOption] = useState<QuickOption>('1hour');
  const [customTime, setCustomTime] = useState<Date | null>(new Date());

  const handleOptionChange = (_: React.MouseEvent<HTMLElement>, newOption: QuickOption | null) => {
    if (newOption) {
      setSelectedOption(newOption);
    }
  };

  const calculateEndTime = (): Date => {
    const now = new Date();

    switch (selectedOption) {
      case 'now':
        return now;
      case '30min':
        return new Date(now.getTime() - 30 * 60 * 1000);
      case '1hour':
        return new Date(now.getTime() - 60 * 60 * 1000);
      case '2hours':
        return new Date(now.getTime() - 2 * 60 * 60 * 1000);
      case 'custom':
        if (customTime) {
          // Validate: must be between session start and now
          if (customTime.getTime() < sessionStart.getTime()) return sessionStart;
          if (customTime.getTime() > now.getTime()) return now;
          return customTime;
        }
        return now;
      default:
        return now;
    }
  };

  const [submitting,setSubmitting] = useState(false);
  const handleConfirm = async () => {
    if(submitting)return;
    setSubmitting(true);
    try {
    if (selectedOption === 'now') {
      await onStopNow();
    } else {
      await onConfirm(calculateEndTime());
    }
    setSelectedOption('1hour');
    setCustomTime(new Date());
    } catch { /* Keep the draft; repository status displays the failure. */ } finally {setSubmitting(false);}
  };

  const handleClose = () => {
    onClose();
    setSelectedOption('1hour');
    setCustomTime(new Date());
  };

  return (
    <LocalizationProvider dateAdapter={AdapterDateFns} adapterLocale={de}>
      <Dialog open={open} onClose={handleClose} maxWidth="xs" fullWidth>
        <DialogTitle>Session running a long time</DialogTitle>
        <DialogContent>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            "{projectName}" has been running since {sessionStart.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}. Did you forget to stop it?
          </Typography>

          <Typography variant="body2" sx={{ mb: 1 }}>
            When did you actually stop?
          </Typography>

          <ToggleButtonGroup
            value={selectedOption}
            exclusive
            onChange={handleOptionChange}
            aria-label="end time option"
            sx={{
              display: 'flex',
              flexWrap: 'wrap',
              gap: 1,
              '& .MuiToggleButton-root': {
                flex: '1 1 auto',
                minWidth: '80px',
              }
            }}
          >
            <ToggleButton value="now">Just now</ToggleButton>
            <ToggleButton value="30min">30 min ago</ToggleButton>
            <ToggleButton value="1hour">1 hour ago</ToggleButton>
            <ToggleButton value="2hours">2 hours ago</ToggleButton>
            <ToggleButton value="custom">Custom</ToggleButton>
          </ToggleButtonGroup>

          {selectedOption === 'custom' && (
            <Box sx={{ mt: 2 }}>
              <DateTimePicker
                label="Actual end time"
                value={customTime}
                onChange={(newValue) => setCustomTime(newValue)}
                minDateTime={sessionStart}
                maxDateTime={new Date()}
                slotProps={{
                  textField: {
                    fullWidth: true,
                    size: 'small'
                  }
                }}
              />
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={handleClose}>Cancel</Button>
          <Button disabled={submitting} onClick={handleConfirm} variant="contained">
            Stop Tracking
          </Button>
        </DialogActions>
      </Dialog>
    </LocalizationProvider>
  );
}
