import { useEffect, useState } from 'react';
import { Alert, Button, Dialog, DialogActions, DialogContent, DialogTitle, Typography } from '@mui/material';
import { useTracker } from './TrackerProvider';
import { getTrackerDatabase, read, write } from './storage';
import { Snapshot, canonical } from './model';
import { backup, downloadBackup, parseBackup, reviewImport } from './migration';
import { CloudTrackerRepository } from './cloud';
/** First-use device reconciliation is explicit; the source is never uploaded on login. */
export function CloudImportReview() {
    const { mode, repository, snapshot, execute, busy, setError } = useTracker();
    const [source, setSource] = useState<Snapshot>();
    const [open, setOpen] = useState(false);
    const [review, setReview] = useState<ReturnType<typeof reviewImport>>();
    const scope = mode === 'cloud' ? (repository as CloudTrackerRepository | null)?.scope : undefined;
    useEffect(() => {
        let alive = true;
        setSource(undefined);
        setOpen(false);
        setReview(undefined);
        if (!scope)
            return;
        void (async () => {
            const db = await getTrackerDatabase();
            const local = await read<Snapshot>(db, 'local:snapshot');
            const legacy = await read(db, 'legacy:backup');
            if (!local && !legacy)
                return;
            const candidate = local ?? parseBackup(legacy);
            const reviewed = await read<string>(db, scope + ':reviewed-source');
            if (alive && reviewed !== canonical(candidate.records))
                setSource(candidate);
        })().catch(e => { if (alive)
            setError(e.message); });
        return () => { alive = false; };
    }, [scope]);
    if (!source || !snapshot || !scope)
        return null;
    const finish = async () => { await write(await getTrackerDatabase(), scope + ':reviewed-source', scope, 'review', canonical(source.records)); setSource(undefined); setOpen(false); };
    return <><Alert severity="info">Review this device’s preserved data against Cloud before retiring the previous installation.<Button onClick={() => { setReview(reviewImport(snapshot, source)); setOpen(true); }}>Review data</Button></Alert>
    <Dialog open={open} onClose={() => setOpen(false)} fullWidth maxWidth="md"><DialogTitle>Review device migration</DialogTitle><DialogContent>
      <Typography>Identical records are skipped. The local source stays intact. Replacements apply only after your review.</Typography>
      <pre style={{ whiteSpace: 'pre-wrap' }}>{review?.differences.join('\n') || 'All records are identical.'}</pre>
      <details><summary>Compare requested and current values</summary><pre style={{ whiteSpace: 'pre-wrap' }}>{JSON.stringify(review?.mutations.map(m => ({ entity: m.entity, id: m.id, current: snapshot.records[m.entity][m.id]?.data, local: m.data })), null, 2)}</pre></details>
      <Button onClick={() => downloadBackup(backup(source), 'preserved-device-data.json')}>Export source</Button>
      <Button onClick={() => downloadBackup(backup(snapshot), 'cloud-before-import.json')}>Export cloud data</Button>
    </DialogContent><DialogActions><Button onClick={() => void finish().catch(e => setError(e.message))}>Keep cloud data</Button><Button disabled={busy || (!review?.mutations.length && review?.pausedProjectId === undefined)} onClick={() => void (async () => { try {
        await execute({ type: 'edit', intendedAt: new Date().toISOString(), pausedProjectId: review!.pausedProjectId, mutations: review!.mutations });
        await finish();
    }
    catch { /* Keep the review open on a conflict or failure. */ } })()}>Import reviewed records</Button></DialogActions></Dialog>
  </>;
}
