import { RxJsonSchema } from 'rxdb';

export interface ProjectHoursAdjustmentDocument {
  id: string;
  userId?: string;
  projectId: string;
  month: string; // YYYY-MM
  hours: number;
  note?: string;
  updatedAt: string;
}

export const projectHoursAdjustmentSchema: RxJsonSchema<ProjectHoursAdjustmentDocument> = {
  version: 1,
  title: 'project hours adjustment schema',
  primaryKey: 'id',
  type: 'object',
  properties: {
    id: {
      type: 'string',
      maxLength: 100,
    },
    userId: {
      type: 'string',
      maxLength: 100,
    },
    projectId: {
      type: 'string',
      maxLength: 100,
    },
    month: {
      type: 'string',
      maxLength: 7,
    },
    hours: {
      type: 'number',
    },
    note: {
      type: 'string',
      maxLength: 500,
    },
    updatedAt: {
      type: 'string',
      format: 'date-time',
      maxLength: 30,
    },
  },
  required: ['id', 'projectId', 'month', 'hours', 'updatedAt'],
  indexes: [['projectId', 'month']],
};
