import { TimeTrackerDatabase } from '../db';
import { Snapshot, emptySnapshot, entities, cleanRecord, validateSnapshot, canonical, Mutation, records } from './model';
export async function legacyBackup(db: TimeTrackerDatabase) {
    const result: Record<string, unknown> = { version: 2 };
    for (const e of entities)
        result[e] = (await db[e].find().exec()).map(d => d.toJSON());
    const state = await db.appState.findOne('appState').exec();
    result.activeProjectId = state?.activeProjectId;
    result.currentSessionStart = state?.currentSessionStart;
    result.pausedProjectId = state?.pausedProjectId;
    return result;
}
export function parseBackup(input: any): Snapshot {
    if (!input || ![undefined, 1, 2, 3].includes(input.version))
        throw new Error('Unsupported backup version');
    if (input.version === 3) {
        const s = structuredClone(input.snapshot) as Snapshot;
        validateSnapshot(s);
        return s;
    }
    if (!Array.isArray(input.projects) || !Array.isArray(input.timeEntries) || !input.settings)
        throw new Error('Invalid backup');
    const s = emptySnapshot();
    for (const e of entities) {
        let rows = input[e] ?? [];
        if (e === 'settings' && !Array.isArray(rows))
            rows = [{ ...rows, id: 'settings' }];
        for (const row of rows) {
            if (['__proto__', 'constructor', 'prototype'].includes(row.id))
                throw new Error('Invalid record ID');
            const data = cleanRecord(row);
            if (e === 'timeEntries')
                data.duration = data.endTime ? Date.parse(data.endTime) - Date.parse(data.startTime) : 0;
            s.records[e][row.id] = { version: 1, data };
        }
    }
    const active = input.projects.filter((p: any) => p.isActive);
    if (active.length > 1 || (active[0] && input.activeProjectId && active[0].id !== input.activeProjectId))
        throw new Error('Multiple active projects require migration review. Export the preserved data and correct the active session before importing.');
    const projectId = active[0]?.id ?? input.activeProjectId;
    const projectStart = active[0]?.currentSessionStart;
    if (projectStart && input.currentSessionStart && Date.parse(projectStart) !== Date.parse(input.currentSessionStart))
        throw new Error('Session start times disagree; migration review is required');
    const start = projectStart ?? input.currentSessionStart;
    const open = records(s, 'timeEntries').filter(e => !e.endTime);
    if (projectId) {
        if (!start)
            throw new Error('Active project has no session start; migration review is required');
        if (open.length && (open.length !== 1 || open[0].projectId !== projectId || Date.parse(open[0].startTime) !== Date.parse(start)))
            throw new Error('Open sessions disagree; migration review is required');
        if (!open.length) {
            const id = 'migrated_' + projectId + '_' + Date.parse(start);
            s.records.timeEntries[id] = { version: 1, correctionVersion: 0, data: { id, projectId, startTime: start, duration: 0 } };
        }
    }
    s.state.activeSessionId = records(s, 'timeEntries').find(e => !e.endTime)?.id ?? null;
    s.state.pausedProjectId = input.pausedProjectId ?? null;
    validateSnapshot(s);
    return s;
}
export function backup(s: Snapshot) { return { version: 3, exportedAt: new Date().toISOString(), snapshot: s }; }
export function reviewImport(current: Snapshot, source: Snapshot) {
    const mutations: Mutation[] = [];
    const differences: string[] = [];
    for (const entity of entities)
        for (const [id, r] of Object.entries(source.records[entity])) {
            if (r.deleted)
                continue;
            const existing = current.records[entity][id];
            if (existing && !existing.deleted && canonical(cleanRecord(existing.data)) === canonical(cleanRecord(r.data)))
                continue;
            mutations.push({ entity, id, expectedVersion: existing?.version ?? 0, data: cleanRecord(r.data) });
            differences.push(`${entity}: ${r.data.name ?? id} — ${existing && !existing.deleted ? 'different: replace after review' : 'new'}`);
        }
    const pausedProjectId = source.state.activeSessionId && source.state.pausedProjectId !== current.state.pausedProjectId ? source.state.pausedProjectId : undefined;
    if (pausedProjectId !== undefined) differences.push(`Paused project: ${current.state.pausedProjectId ?? 'none'} → ${pausedProjectId ?? 'none'} (review required)`);
    return { mutations, differences, pausedProjectId };
}
export function downloadBackup(data: unknown, filename = 'time-tracker-backup.json') {
    const url = URL.createObjectURL(new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    a.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
}
