import { useState, useEffect, useCallback, Suspense, lazy, useMemo } from 'react';
import {
  ThemeProvider,
  createTheme,
  CssBaseline,
  AppBar,
  Toolbar,
  Typography,
  BottomNavigation,
  BottomNavigationAction,
  Box,
  Snackbar,
  Alert,
  CircularProgress,
  Tooltip,
  IconButton,
  Button,
  PaletteMode
} from '@mui/material';
import {
  Dashboard as DashboardIcon,
  BarChart as StatsIcon,
  History as HistoryIcon,
  Settings as SettingsIcon,
  GetApp as ReportsIcon,
  DarkMode as DarkModeIcon,
  LightMode as LightModeIcon,
  Undo as UndoIcon
} from '@mui/icons-material';

import { ProjectGrid } from './components/ProjectGrid';
import { AddProjectDialog } from './components/AddProjectDialog';
import { EditProjectDialog } from './components/EditProjectDialog';
import { ErrorBoundary } from './components/ErrorBoundary';
import { RetroactiveStartDialog } from './components/RetroactiveStartDialog';
import { ForgotToStopDialog } from './components/ForgotToStopDialog';
import { TrackerProvider, TrackerGate, TrackerStatus } from './tracker/TrackerProvider';
import { useTimeTrackerRx, Project, TimeEntry } from './hooks/useTimeTrackerRx';
import { useSync } from './hooks/useSync';
import { formatDuration } from './utils/timeUtils';

// Lazy load heavy panels for code splitting
const StatsPanel = lazy(() => import('./components/StatsPanel').then(m => ({ default: m.StatsPanel })));
const HistoryPanel = lazy(() => import('./components/HistoryPanel').then(m => ({ default: m.HistoryPanel })));
const ReportsPanel = lazy(() => import('./components/ReportsPanel').then(m => ({ default: m.ReportsPanel })));
const SettingsPanel = lazy(() => import('./components/SettingsPanel').then(m => ({ default: m.SettingsPanel })));

// Theme mode storage key
const THEME_MODE_KEY = 'timeTracker_themeMode';

// Undo action types
interface UndoAction {
  type: 'delete_project' | 'delete_entry';
  data: Project | TimeEntry;
  timestamp: number;
}

const UNDO_TIMEOUT = 5000; // 5 seconds to undo

function AppContent() {
  const {
    projects,
    isSaving,
    clearDataset,
    projectTree,
    timeEntries,
    settings,
    activeProjectId,
    currentSessionStart,
    isLoaded,
    toggleProject,
    startTracking,
    addProject,
    updateProject,
    deleteProject,
    updateSettings,
    updateTimeEntry,
    updateTimeEntries,
    deleteTimeEntry,
    restoreProject,
    restoreTimeEntry,
    insertTimeEntry,
    splitTimeEntry,
    overtimeAdjustments,
    totalAdjustmentHours,
    addOvertimeAdjustment,
    deleteOvertimeAdjustment,
    stopTrackingAt,
    stopTracking,
    updateSessionStart,
    getAdjustmentForProjectMonth,
    getTotalAdjustmentHoursForMonth,
    totalAllProjectOffsets,
    setProjectHoursAdjustment,
  } = useTimeTrackerRx();

  const { syncState } = useSync();

  const [currentTab, setCurrentTab] = useState(0);
  const [addProjectOpen, setAddProjectOpen] = useState(false);
  const [editProjectOpen, setEditProjectOpen] = useState(false);
  const [editingProject, setEditingProject] = useState<Project | null>(null);
  const [currentTime, setCurrentTime] = useState(new Date());
  const [retroactiveStartDialog, setRetroactiveStartDialog] = useState<{
    open: boolean;
    projectId: string;
    projectName: string;
    projectIcon: string;
    start: (at: Date) => Promise<void>;
  } | null>(null);
  const [forgotToStopOpen, setForgotToStopOpen] = useState(false);
  const [forgotSession, setForgotSession] = useState<{projectName:string;start:Date;stopAt:(at:Date)=>Promise<void>;stopNow:()=>Promise<void>} | null>(null);
  const [themeMode, setThemeMode] = useState<PaletteMode>(() => {
    const stored = localStorage.getItem(THEME_MODE_KEY);
    return (stored === 'dark' || stored === 'light') ? stored : 'light';
  });
  const [undoAction, setUndoAction] = useState<UndoAction | null>(null);
  const [snackbar, setSnackbar] = useState<{ open: boolean; message: string; severity: 'success' | 'error' | 'info' }>({
    open: false,
    message: '',
    severity: 'info'
  });

  // Create theme based on mode
  const theme = useMemo(() => createTheme({
    palette: {
      mode: themeMode,
      primary: {
        main: '#1976d2',
      },
      secondary: {
        main: '#dc004e',
      },
      ...(themeMode === 'dark' && {
        background: {
          default: '#121212',
          paper: '#1e1e1e',
        },
      }),
    },
    components: {
      MuiBottomNavigation: {
        styleOverrides: {
          root: {
            position: 'fixed',
            bottom: 0,
            left: 0,
            right: 0,
            zIndex: 1000,
          },
        },
      },
    },
  }), [themeMode]);

  // Only run timer when there's an active project
  useEffect(() => {
    if (!activeProjectId) return;

    const timer = setInterval(() => {
      setCurrentTime(new Date());
    }, 1000);
    return () => clearInterval(timer);
  }, [activeProjectId]);

  // Handle undo timeout
  useEffect(() => {
    if (!undoAction) return;

    const timeout = setTimeout(() => {
      setUndoAction(null);
    }, UNDO_TIMEOUT);

    return () => clearTimeout(timeout);
  }, [undoAction]);

  const toggleTheme = useCallback(() => {
    setThemeMode(prev => {
      const next = prev === 'light' ? 'dark' : 'light';
      localStorage.setItem(THEME_MODE_KEY, next);
      return next;
    });
  }, []);

  const getCurrentSessionDuration = useCallback(() => {
    if (activeProjectId && currentSessionStart) {
      return currentTime.getTime() - currentSessionStart.getTime();
    }
    return 0;
  }, [activeProjectId, currentSessionStart, currentTime]);

  const getActiveProject = useCallback(() => {
    return projects.find(p => p.id === activeProjectId);
  }, [projects, activeProjectId]);

  const handleToggleProject = useCallback(async (projectId: string) => {
    const wasActive = activeProjectId === projectId;

    // Check if a child of this project is currently active
    const activeChildOfThis = activeProjectId
      ? projects.find(p => p.id === activeProjectId && p.parentId === projectId)
      : null;

    const project = projects.find(p => p.id === projectId);

    if (wasActive || activeChildOfThis) {
      // Stop whichever is actually active (could be a child)
      const idToStop = activeChildOfThis ? activeChildOfThis.id : projectId;
      await toggleProject(idToStop);
      setSnackbar({
        open: true,
        message: 'Time tracking stopped',
        severity: 'info'
      });
    } else if (projectId === 'break') {
      // Break has special pause/resume logic - use toggleProject directly
      await toggleProject(projectId);
      const isCurrentlyOnBreak = activeProjectId === 'break';
      setSnackbar({
        open: true,
        message: isCurrentlyOnBreak ? 'Resumed from break' : 'Break started',
        severity: 'info'
      });
    } else {
      // Starting a non-break project - show retroactive dialog
      if (project) {
        // Guard against sync race: project doc says active but appState hasn't caught up yet
        if (project.isActive && project.currentSessionStart) {
          return;
        }
        setRetroactiveStartDialog({
          open: true,
          projectId: project.id,
          projectName: project.name,
          projectIcon: project.icon,
          start: (at:Date) => startTracking(project.id, at),
        });
      }
    }
  }, [activeProjectId, toggleProject, projects, startTracking]);

  const handleRetroactiveStartConfirm = useCallback(async (startTime: Date) => {
    if (!retroactiveStartDialog) return;

    const { projectName } = retroactiveStartDialog;
    const now = new Date();
    const isRetroactive = startTime.getTime() < now.getTime() - 60000; // More than 1 minute ago

    await retroactiveStartDialog.start(startTime);

    setSnackbar({
      open: true,
      message: isRetroactive
        ? `Started tracking ${projectName} (backdated)`
        : `Started tracking: ${projectName}`,
      severity: 'success'
    });

    setRetroactiveStartDialog(null);
  }, [retroactiveStartDialog, startTracking]);

  const handleDeleteProject = useCallback(async (projectId: string) => {
    const project = projects.find(p => p.id === projectId);
    if (!project) return;

    await deleteProject(projectId);
    // Offer undo only after acceptance.
    setUndoAction({
      type: 'delete_project',
      data: project,
      timestamp: Date.now()
    });

    setSnackbar({
      open: true,
      message: `Deleted project: ${project.name}`,
      severity: 'info'
    });
  }, [projects, deleteProject]);

  const handleDeleteEntry = useCallback(async (entryId: string) => {
    const entry = timeEntries.find(e => e.id === entryId);
    if (!entry) return;

    await deleteTimeEntry(entryId);
    // Offer undo only after acceptance.
    setUndoAction({
      type: 'delete_entry',
      data: entry,
      timestamp: Date.now()
    });
  }, [timeEntries, deleteTimeEntry]);

  const handleUndo = useCallback(async () => {
    if (!undoAction) return;

    if (undoAction.type === 'delete_project' && restoreProject) {
      await restoreProject(undoAction.data as Project);
      setSnackbar({
        open: true,
        message: `Restored project: ${(undoAction.data as Project).name}`,
        severity: 'success'
      });
    } else if (undoAction.type === 'delete_entry' && restoreTimeEntry) {
      await restoreTimeEntry(undoAction.data as TimeEntry);
      setSnackbar({
        open: true,
        message: 'Time entry restored',
        severity: 'success'
      });
    }

    setUndoAction(null);
  }, [undoAction, restoreProject, restoreTimeEntry]);

  const handleForgotToStopConfirm = useCallback(async (endTime: Date) => {
    await forgotSession?.stopAt(endTime);
    setForgotToStopOpen(false);
    setSnackbar({
      open: true,
      message: 'Session stopped with adjusted end time',
      severity: 'success'
    });
  }, [forgotSession]);

  const handleForgotToStopNow = useCallback(async () => {
    await forgotSession?.stopNow();
    setForgotToStopOpen(false);
    setSnackbar({
      open: true,
      message: 'Time tracking stopped',
      severity: 'info'
    });
  }, [forgotSession]);

  const handleEditProject = useCallback((project: Project) => {
    setEditingProject(project);
    setEditProjectOpen(true);
  }, []);

  const handleSaveProject = useCallback(async (projectId: string, updates: {
    version?: number;
    name: string;
    icon: string;
    color: string;
    targetType: 'none' | 'hours' | 'percentage';
    targetValue?: number;
    initialHours?: number;
    budgetHours?: number;
    budgetDeadline?: string;
    parentId?: string;
  }) => {
    await updateProject(projectId, updates);
    setSnackbar({
      open: true,
      message: 'Project updated successfully!',
      severity: 'success'
    });
  }, [updateProject]);

  const currentSessionDuration = getCurrentSessionDuration();
  const activeProject = getActiveProject();

  // Loading screen
  if (!isLoaded) {
    return (
      <ThemeProvider theme={theme}>
        <CssBaseline />
        <Box sx={{
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          height: '100vh',
          flexDirection: 'column',
          gap: 2
        }}>
          <CircularProgress size={60} />
          <Typography variant="h6">Loading Time Tracker...</Typography>
        </Box>
      </ThemeProvider>
    );
  }

  const LoadingFallback = (
    <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 200 }}>
      <CircularProgress />
    </Box>
  );

  const renderContent = () => {
    switch (currentTab) {
      case 0:
        return (
          <ProjectGrid
            projects={projects}
            projectTree={projectTree}
            timeEntries={timeEntries}
            settings={settings}
            activeProjectId={activeProjectId}
            onToggleProject={(...args) => { void handleToggleProject(...args).catch(() => {}); }}
            onStartProject={startTracking}
            onDeleteProject={(...args) => { void handleDeleteProject(...args).catch(() => {}); }}
            onEditProject={handleEditProject}
            onAddProject={() => setAddProjectOpen(true)}
          />
        );
      case 1:
        return (
          <ErrorBoundary>
            <Suspense fallback={LoadingFallback}>
              <StatsPanel
                projects={projects}
                timeEntries={timeEntries}
                settings={settings}
                activeProjectId={activeProjectId}
                currentSessionStart={currentSessionStart}
                totalAdjustmentHours={totalAdjustmentHours}
                getAdjustmentForProjectMonth={getAdjustmentForProjectMonth}
                getTotalAdjustmentHoursForMonth={getTotalAdjustmentHoursForMonth}
                totalAllProjectOffsets={totalAllProjectOffsets}
                onSetProjectHoursAdjustment={setProjectHoursAdjustment}
              />
            </Suspense>
          </ErrorBoundary>
        );
      case 2:
        return (
          <ErrorBoundary>
            <Suspense fallback={LoadingFallback}>
              <HistoryPanel
                timeEntries={timeEntries}
                projects={projects}
                onUpdateEntry={updateTimeEntry}
                onUpdateEntries={updateTimeEntries}
                onDeleteEntry={(...args) => { void handleDeleteEntry(...args).catch(() => {}); }}
                onInsertEntry={insertTimeEntry}
                onSplitEntry={splitTimeEntry}
                activeProjectId={activeProjectId}
                currentSessionStart={currentSessionStart}
                onUpdateSessionStart={updateSessionStart}
              />
            </Suspense>
          </ErrorBoundary>
        );
      case 3:
        return (
          <ErrorBoundary>
            <Suspense fallback={LoadingFallback}>
              <ReportsPanel
                timeEntries={timeEntries}
                projects={projects}
                settings={settings}
                totalAdjustmentHours={totalAdjustmentHours}
                totalAllProjectOffsets={totalAllProjectOffsets}
              />
            </Suspense>
          </ErrorBoundary>
        );
      case 4:
        return (
          <ErrorBoundary>
            <Suspense fallback={LoadingFallback}>
              <SettingsPanel
                settings={settings}
                onSave={updateSettings}
                overtimeAdjustments={overtimeAdjustments}
                onAddAdjustment={addOvertimeAdjustment}
                onDeleteAdjustment={deleteOvertimeAdjustment}
                onClearDatabase={clearDataset}
              />
            </Suspense>
          </ErrorBoundary>
        );
      default:
        return null;
    }
  };

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <Box sx={{ pb: 7 }}>
        <AppBar position="static">
          <Toolbar>
            <Typography variant="h6" component="div" sx={{ flexGrow: 1 }}>
              Time Tracker
            </Typography>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
              {/* Theme Toggle */}
              <Tooltip title={themeMode === 'light' ? 'Switch to dark mode' : 'Switch to light mode'} arrow>
                <IconButton color="inherit" onClick={toggleTheme} size="small" aria-label={themeMode === 'light' ? 'Switch to dark mode' : 'Switch to light mode'}>
                  {themeMode === 'light' ? <DarkModeIcon /> : <LightModeIcon />}
                </IconButton>
              </Tooltip>

              {/* Sync Status Indicator */}
              <Tooltip
                title={
                  syncState.status === 'connected'
                    ? 'Cloud: Connected'
                    : syncState.isEnabled
                      ? 'Cloud: Connecting...'
                      : 'Local storage'
                }
                arrow
              >
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, cursor: 'help' }}>
                  <Typography variant="caption" sx={{ fontSize: '0.75rem' }}>
                    {syncState.status === 'connected' ? '🔄' : syncState.isEnabled ? '📡' : '💾'}
                  </Typography>
                </Box>
              </Tooltip>

              {activeProject && (
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, ml: 1 }} aria-live="polite">
                  <Button
                    size="small"
                    color="inherit"
                    onClick={() => {if(activeProject && currentSessionStart){setForgotSession({projectName:activeProject.name,start:currentSessionStart,stopAt:stopTrackingAt,stopNow:stopTracking});setForgotToStopOpen(true);}}}
                    sx={{ fontSize: '0.65rem', minWidth: 'auto', px: 0.5, opacity: 0.8 }}
                    aria-label="Forgot to stop tracking"
                  >
                    Forgot?
                  </Button>
                  <Box sx={{ textAlign: 'right' }}>
                    <Typography variant="body2">
                      {activeProject.name}
                    </Typography>
                    <Typography variant="caption">
                      {formatDuration(currentSessionDuration)}
                    </Typography>
                  </Box>
                </Box>
              )}
            </Box>
          </Toolbar>
        </AppBar>

        <TrackerStatus />
        <Box component="fieldset" disabled={isSaving} sx={{border:0,p:0,m:0,minWidth:0}}>{renderContent()}</Box>

        <BottomNavigation
          value={currentTab}
          onChange={(_, newValue) => setCurrentTab(newValue)}
          showLabels
        >
          <BottomNavigationAction label="Projects" icon={<DashboardIcon />} />
          <BottomNavigationAction label="Stats" icon={<StatsIcon />} />
          <BottomNavigationAction label="History" icon={<HistoryIcon />} />
          <BottomNavigationAction label="Reports" icon={<ReportsIcon />} />
          <BottomNavigationAction label="Settings" icon={<SettingsIcon />} />
        </BottomNavigation>
      </Box>

      <AddProjectDialog
        open={addProjectOpen}
        onClose={() => setAddProjectOpen(false)}
        onAdd={addProject}
        availableParents={projects.filter(p => p.id !== 'break' && p.id !== 'work' && !p.parentId)}
      />

      <EditProjectDialog
        open={editProjectOpen}
        onClose={() => {
          setEditProjectOpen(false);
          setEditingProject(null);
        }}
        project={editingProject}
        onSave={handleSaveProject}
        onDelete={deleteProject}
        availableParents={projects.filter(p => p.id !== 'break' && p.id !== 'work' && !p.parentId)}
      />

      {/* Retroactive Start Dialog */}
      {retroactiveStartDialog && (
        <RetroactiveStartDialog
          open={retroactiveStartDialog.open}
          projectName={retroactiveStartDialog.projectName}
          projectIcon={retroactiveStartDialog.projectIcon}
          onClose={() => setRetroactiveStartDialog(null)}
          onConfirm={handleRetroactiveStartConfirm}
        />
      )}

      {/* Forgot to Stop Dialog */}
      {forgotSession && (
        <ForgotToStopDialog
          open={forgotToStopOpen}
          projectName={forgotSession.projectName}
          sessionStart={forgotSession.start}
          onClose={() => setForgotToStopOpen(false)}
          onConfirm={handleForgotToStopConfirm}
          onStopNow={(...args) => { void handleForgotToStopNow(...args).catch(() => {}); }}
        />
      )}

      {/* Undo Snackbar */}
      <Snackbar
        open={!!undoAction}
        autoHideDuration={UNDO_TIMEOUT}
        onClose={() => setUndoAction(null)}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
        sx={{ mb: 7 }}
      >
        <Alert
          severity="warning"
          action={
            <Button color="inherit" size="small" startIcon={<UndoIcon />} onClick={() => { void handleUndo().catch(() => {}); }}>
              Undo
            </Button>
          }
        >
          {undoAction?.type === 'delete_project'
            ? `Project "${(undoAction.data as Project).name}" deleted`
            : 'Time entry deleted'}
        </Alert>
      </Snackbar>

      {/* General Snackbar */}
      <Snackbar
        open={snackbar.open && !undoAction}
        autoHideDuration={3000}
        onClose={() => setSnackbar(prev => ({ ...prev, open: false }))}
      >
        <Alert
          onClose={() => setSnackbar(prev => ({ ...prev, open: false }))}
          severity={snackbar.severity}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </ThemeProvider>
  );
}

// Wrap the app with DatabaseProvider
function App() {
  return (
    <TrackerProvider><TrackerGate>
      <AppContent />
    </TrackerGate></TrackerProvider>
  );
}

export default App;
