import { BehaviorSubject } from 'rxjs';
import { Command, Outcome, Snapshot, Receipt, canonical, applyCommand } from './model';
import { TrackerDatabase, read, write } from './storage';
export interface RepositoryStatus {
    connection: 'local' | 'connecting' | 'connected' | 'offline' | 'error';
    pending: number;
    confirmationPending: boolean;
    needsConfirmation: Command[];
    lastRefresh?: string;
    error?: string;
}
export interface TrackerRepository {
    snapshot$: BehaviorSubject<Snapshot | null>;
    status$: BehaviorSubject<RepositoryStatus>;
    execute(command: Command): Promise<Outcome>;
    refresh(): Promise<void>;
    close(): void;
}
interface Journal {
    command: Command;
    prepared?: {
        snapshot: Snapshot;
        outcome: Outcome;
    };
    outcome?: Outcome;
}
export class LocalTrackerRepository implements TrackerRepository {
    snapshot$ = new BehaviorSubject<Snapshot | null>(null);
    status$ = new BehaviorSubject<RepositoryStatus>({ connection: 'local', pending: 0, confirmationPending: false, needsConfirmation: [] });
    private closed = false;
    private draining = false;
    private leader = false;
    private subscriptions: {
        unsubscribe(): void;
    }[] = [];
    constructor(private db: TrackerDatabase, private seed: () => Promise<Snapshot>, readonly scope = 'local') { }
    async initialize() {
        this.subscriptions.push(this.db.documents.find().$.subscribe(() => { void this.refresh().catch(e => this.fail(e)); if (this.leader)
            void this.drain(); }));
        void this.db.waitForLeadership().then(async () => {
            if (this.closed)
                return;
            this.leader = true;
            if (!await read(this.db, this.scope + ':snapshot'))
                await write(this.db, this.scope + ':snapshot', this.scope, 'snapshot', await this.seed());
            await this.drain();
        }).catch(e => this.fail(e));
        await this.refresh();
        return this;
    }
    private fail(e: unknown) { this.status$.next({ ...this.status$.value, error: e instanceof Error ? e.message : String(e) }); }
    async refresh() {
        const journals = await this.db.documents.find({ selector: { scope: this.scope, kind: 'journal' } }).exec();
        // A prepared journal must finish before any snapshot is published.
        if (journals.some(d => { const j: Journal = JSON.parse(d.value); return j.prepared && !j.outcome; }))
            return;
        const s = await read<Snapshot>(this.db, this.scope + ':snapshot');
        if (s && (!this.snapshot$.value || s.revision > this.snapshot$.value.revision))
            this.snapshot$.next(s);
    }
    private async drain() {
        if (this.draining || this.closed)
            return;
        this.draining = true;
        try {
            for (;;) {
                const docs = await this.db.documents.find({ selector: { scope: this.scope, kind: 'journal' } }).exec();
                const waiting = docs.map(d => ({ id: d.id, j: JSON.parse(d.value) as Journal })).filter(({ j }) => !j.outcome).sort((a, b) => Number(!!b.j.prepared) - Number(!!a.j.prepared) || a.j.command.issuedAt.localeCompare(b.j.command.issuedAt) || a.id.localeCompare(b.id));
                if (!waiting.length)
                    break;
                for (const { id, j } of waiting) {
                    let prepared = j.prepared;
                    if (!prepared) {
                        const s = await read<Snapshot>(this.db, this.scope + ':snapshot');
                        if (!s)
                            throw new Error('Migration must complete before editing');
                        prepared = applyCommand(s, j.command, Date.now());
                        // Durable write-ahead journal: resolved IDs and full mutation result precede application.
                        await write(this.db, id, this.scope, 'journal', { ...j, prepared });
                    }
                    const current = await read<Snapshot>(this.db, this.scope + ':snapshot');
                    if (!current || prepared.snapshot.revision >= current.revision)
                        await write(this.db, this.scope + ':snapshot', this.scope, 'snapshot', prepared.snapshot);
                    await write(this.db, id, this.scope, 'journal', { command: j.command, outcome: prepared.outcome });
                }
            }
            await this.refresh();
        }
        catch (e) {
            this.fail(e);
        }
        finally {
            this.draining = false;
        }
    }
    async execute(command: Command): Promise<Outcome> {
        if (!this.snapshot$.value || this.closed)
            throw new Error('Repository is not ready');
        const id = this.scope + ':op:' + command.operationId;
        const existing = await read<Journal>(this.db, id);
        if (existing && canonical(existing.command) !== canonical(command))
            return { status: 'rejected', revision: this.snapshot$.value.revision, message: 'Operation ID reused with different payload' };
        if (existing?.outcome)
            return existing.outcome;
        if (!existing) {
            // insert, never upsert: another tab cannot replace a pending operation payload.
            try {
                await this.db.documents.insert({ id, scope: this.scope, kind: 'journal', value: JSON.stringify({ command }) });
            }
            catch {
                const raced = await read<Journal>(this.db, id);
                if (!raced || canonical(raced.command) !== canonical(command))
                    throw new Error('Operation ID collision');
            }
        }
        if (this.leader)
            void this.drain();
        return new Promise((resolve, reject) => {
            const subscription = this.db.documents.findOne(id).$.subscribe(doc => {
                const j = doc ? JSON.parse(doc.value) as Journal : undefined;
                if (j?.outcome) {
                    void this.refresh().then(() => resolve(j.outcome!));
                    queueMicrotask(() => subscription.unsubscribe());
                }
                else if (this.status$.value.error) {
                    reject(new Error(this.status$.value.error));
                    queueMicrotask(() => subscription.unsubscribe());
                }
            });
        });
    }
    close() { this.closed = true; this.subscriptions.forEach(s => s.unsubscribe()); }
}
export function savedReceipt(receipt: Receipt | undefined, command: Command): Outcome | undefined {
    if (!receipt)
        return undefined;
    return canonical(receipt.command) === canonical(command) ? receipt.outcome : { status: 'rejected', revision: receipt.outcome.revision, message: 'Operation ID reused with different payload' };
}
