import { RxJsonSchema } from 'rxdb';

// Local-only state - NOT synced between devices
export interface AppStateDocument {
  id: string; // Always 'appState' - singleton
  activeProjectId?: string;
  pausedProjectId?: string;
  currentSessionStart?: string;
  supabaseUrl?: string;
  supabaseApiKey?: string;
  themeMode: 'light' | 'dark';
}

export const appStateSchema: RxJsonSchema<AppStateDocument> = {
  version: 4,
  title: 'local app state schema',
  primaryKey: 'id',
  type: 'object',
  properties: {
    id: {
      type: 'string',
      maxLength: 50,
    },
    activeProjectId: {
      type: 'string',
      maxLength: 100,
    },
    pausedProjectId: {
      type: 'string',
      maxLength: 100,
    },
    currentSessionStart: {
      type: 'string',
      format: 'date-time',
      maxLength: 30,
    },
    supabaseUrl: {
      type: 'string',
      maxLength: 200,
    },
    supabaseApiKey: {
      type: 'string',
      maxLength: 500,
    },
    themeMode: {
      type: 'string',
      enum: ['light', 'dark'],
    },
  },
  required: ['id', 'themeMode'],
};
