import { RxJsonSchema } from 'rxdb';

export interface SettingsDocument {
  id: string; // Always 'settings' - singleton
  userId?: string;
  dailyTargetHours: number;
  workdays: number[];
  vacationDays: string[];
  trackingStartDate: string;
  initialOvertimeHours?: number;
  paidOvertimePerMonth?: number;
  paidOvertimeOverrides?: Record<string, number>;
  updatedAt: string;
}

export const settingsSchema: RxJsonSchema<SettingsDocument> = {
  version: 5,
  title: 'settings schema',
  primaryKey: 'id',
  type: 'object',
  properties: {
    id: {
      type: 'string',
      maxLength: 50,
    },
    userId: {
      type: 'string',
      maxLength: 100,
    },
    dailyTargetHours: {
      type: 'number',
    },
    workdays: {
      type: 'array',
      items: {
        type: 'number',
      },
    },
    vacationDays: {
      type: 'array',
      items: {
        type: 'string',
      },
    },
    trackingStartDate: {
      type: 'string',
      maxLength: 20,
    },
    initialOvertimeHours: {
      type: 'number',
    },
    paidOvertimePerMonth: {
      type: 'number',
    },
    paidOvertimeOverrides: {
      type: 'object',
      additionalProperties: {
        type: 'number',
      },
    },
    updatedAt: {
      type: 'string',
      format: 'date-time',
      maxLength: 30,
    },
  },
  required: ['id', 'dailyTargetHours', 'workdays', 'vacationDays', 'trackingStartDate', 'updatedAt'],
};
